values ('RD-A1-003', 'A1', 'notice', 'housing', 1, 'Записка на холодильнику', 'Poruka na hladnjaku',
        'Dragi Tarase,
danas radim do kasno. Molim te:
– izvadi rublje iz perilice i objesi ga na balkon;
– iznesi smeće;
– nahrani mačku.
Ručak je u hladnjaku, samo ga zagrij. Vidimo se navečer!
Olena',
        'Дорогий Тарасе,
сьогодні я працюю допізна. Будь ласка:
– вийми білизну з пральної машини й повісь її на балкон;
– винеси сміття;
– погодуй кішку.
Обід у холодильнику, тільки розігрій його. Побачимося ввечері!
Олена',
        '[{"form": "dragi", "lemma": "drag", "ua": "дорогий; милий, приємний", "lesson": true}, {"form": "tarase", "lemma": "Taras", "ua": "Тарас (ім’я, кличний відмінок)", "lesson": false}, {"form": "danas", "lemma": "danas", "ua": "сьогодні", "lesson": true}, {"form": "radim", "lemma": "raditi", "ua": "працювати, робити", "lesson": true}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "kasno", "lemma": "kasno", "ua": "пізно", "lesson": true}, {"form": "molim", "lemma": "molim", "ua": "Прошу / Будь ласка / Що (ви сказали)?", "lesson": true}, {"form": "te", "lemma": "te", "ua": "тебе (займенник)", "lesson": false}, {"form": "izvadi", "lemma": "izvaditi", "ua": "видалити (зуб); вийняти", "lesson": true}, {"form": "rublje", "lemma": "rublje", "ua": "білизна (для прання)", "lesson": true}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": false}, {"form": "perilice", "lemma": "perilica", "ua": "пральна машина", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "objesi", "lemma": "objesiti", "ua": "повісити", "lesson": true}, {"form": "ga", "lemma": "ga", "ua": "його (займенник)", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "balkon", "lemma": "balkon", "ua": "балкон", "lesson": true}, {"form": "iznesi", "lemma": "iznositi", "ua": "виносити", "lesson": true}, {"form": "smeće", "lemma": "smeće", "ua": "сміття", "lesson": true}, {"form": "nahrani", "lemma": "hraniti", "ua": "годувати", "lesson": true}, {"form": "mačku", "lemma": "mačka", "ua": "кішка", "lesson": true}, {"form": "ručak", "lemma": "ručak", "ua": "обід", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "hladnjaku", "lemma": "hladnjak", "ua": "холодильник", "lesson": true}, {"form": "samo", "lemma": "samo", "ua": "тільки; лише", "lesson": false}, {"form": "zagrij", "lemma": "zagrijati", "ua": "розігріти; нагріти", "lesson": true}, {"form": "vidimo", "lemma": "vidjeti", "ua": "бачити", "lesson": false}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "navečer", "lemma": "navečer", "ua": "ввечері", "lesson": true}, {"form": "olena", "lemma": "Olena", "ua": "Олена (ім’я)", "lesson": false}]'::jsonb,
        '[{"question_ua": "Чому Олена пише записку?", "options": ["Вона працює допізна", "Вона в лікарні", "Вона на морі"], "answer": "Вона працює допізна"}, {"question_ua": "Куди треба повісити білизну?", "options": ["На балкон", "У ванну", "У кімнату"], "answer": "На балкон"}, {"question_ua": "Де обід?", "options": ["У холодильнику", "На столі", "У духовці"], "answer": "У холодильнику"}]'::jsonb, 32, 1.000, 3, 'PUBLISHED', 'claude_reading_a1_v1')
