values ('RD-A1-004', 'A1', 'story', 'small_talk', 1, 'Звичайний день Тараса', 'Tarasov običan dan',
        'Taras živi u Zagrebu. Svaki dan se budi u šest i pol. Prvo se tušira, a onda doručkuje s obitelji. Na posao ide tramvajem. Radi u skladištu od osam do četiri. Poslije posla ide u trgovinu ili u park sa psom. Navečer obično čita ili gleda film. Spava u jedanaest, jer je ujutro opet rano.',
        'Тарас живе в Загребі. Щодня він прокидається о пів на сьому. Спочатку приймає душ, а потім снідає з родиною. На роботу їде трамваєм. Працює на складі з восьмої до четвертої. Після роботи йде в магазин або в парк із собакою. Увечері зазвичай читає або дивиться фільм. Лягає спати об одинадцятій, бо вранці знову рано.',
        '[{"form": "taras", "lemma": "Taras", "ua": "Тарас (ім’я)", "lesson": false}, {"form": "živi", "lemma": "živjeti", "ua": "жити", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "zagrebu", "lemma": "Zagreb", "ua": "Загреб", "lesson": false}, {"form": "svaki", "lemma": "svaki", "ua": "кожен", "lesson": false}, {"form": "dan", "lemma": "dan", "ua": "день", "lesson": false}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "budi", "lemma": "buditi se", "ua": "прокидатися", "lesson": true}, {"form": "šest", "lemma": "šest", "ua": "шість", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "pol", "lemma": "pol", "ua": "половина («šest i pol» — пів на сьому)", "lesson": false}, {"form": "prvo", "lemma": "prvo", "ua": "спочатку", "lesson": false}, {"form": "tušira", "lemma": "tuširati se", "ua": "приймати душ", "lesson": true}, {"form": "a", "lemma": "a", "ua": "а; і", "lesson": false}, {"form": "onda", "lemma": "onda", "ua": "потім; тоді", "lesson": false}, {"form": "doručkuje", "lemma": "doručkovati", "ua": "снідати", "lesson": true}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "obitelji", "lemma": "obitelj", "ua": "сім''я, родина", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "posao", "lemma": "posao", "ua": "робота / справа", "lesson": true}, {"form": "ide", "lemma": "ići", "ua": "іти, їхати", "lesson": true}, {"form": "tramvajem", "lemma": "tramvaj", "ua": "трамвай", "lesson": true}, {"form": "radi", "lemma": "raditi", "ua": "працювати, робити", "lesson": true}, {"form": "skladištu", "lemma": "skladište", "ua": "склад", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "osam", "lemma": "osam", "ua": "вісім", "lesson": true}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "četiri", "lemma": "četiri", "ua": "чотири", "lesson": true}, {"form": "poslije", "lemma": "poslije", "ua": "після", "lesson": false}, {"form": "posla", "lemma": "posao", "ua": "робота / справа", "lesson": true}, {"form": "trgovinu", "lemma": "trgovina", "ua": "магазин / крамниця", "lesson": true}, {"form": "ili", "lemma": "ili", "ua": "або", "lesson": true}, {"form": "park", "lemma": "park", "ua": "парк", "lesson": true}, {"form": "sa", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "psom", "lemma": "pas", "ua": "собака", "lesson": true}, {"form": "navečer", "lemma": "navečer", "ua": "ввечері", "lesson": true}, {"form": "obično", "lemma": "obično", "ua": "зазвичай", "lesson": true}, {"form": "čita", "lemma": "čitati", "ua": "читати", "lesson": true}, {"form": "gleda", "lemma": "gledati", "ua": "дивитися", "lesson": true}, {"form": "film", "lemma": "film", "ua": "фільм", "lesson": true}, {"form": "spava", "lemma": "spavati", "ua": "спати", "lesson": true}, {"form": "jedanaest", "lemma": "jedanaest", "ua": "одинадцять", "lesson": true}, {"form": "jer", "lemma": "jer", "ua": "тому що / бо", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "ujutro", "lemma": "ujutro", "ua": "вранці", "lesson": true}, {"form": "opet", "lemma": "opet", "ua": "знову", "lesson": true}, {"form": "rano", "lemma": "rano", "ua": "рано", "lesson": true}]'::jsonb,
        '[{"question_ua": "Як Тарас їде на роботу?", "options": ["Трамваєм", "Автобусом", "Пішки"], "answer": "Трамваєм"}, {"question_ua": "Де працює Тарас?", "options": ["На складі", "У школі", "У готелі"], "answer": "На складі"}, {"question_ua": "Що він робить увечері?", "options": ["Читає або дивиться фільм", "Працює", "Тренується"], "answer": "Читає або дивиться фільм"}]'::jsonb, 55, 0.982, 4, 'PUBLISHED', 'claude_reading_a1_v1')
