on": true}, {"form": "sa", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "svake", "lemma": "svaki", "ua": "кожен", "lesson": false}, {"form": "strane", "lemma": "strana", "ua": "бік; сторона", "lesson": false}, {"form": "palačinke", "lemma": "palačinka", "ua": "млинець", "lesson": false}, {"form": "jedite", "lemma": "jesti", "ua": "їсти", "lesson": true}, {"form": "pekmezom", "lemma": "pekmez", "ua": "джем; повидло", "lesson": true}, {"form": "medom", "lemma": "med", "ua": "мед", "lesson": true}, {"form": "ili", "lemma": "ili", "ua": "або", "lesson": true}, {"form": "čokoladom", "lemma": "čokolada", "ua": "шоколад", "lesson": false}, {"form": "dobar", "lemma": "dobar", "ua": "добрий; гарний", "lesson": false}, {"form": "tek", "lemma": "tek", "ua": "лише; тільки-но, щойно", "lesson": true}]'::jsonb,
        '[{"question_ua": "Скільки яєць потрібно?", "options": ["Два", "Три", "Одне"], "answer": "Два"}, {"question_ua": "Скільки часу пекти кожен бік?", "options": ["Хвилину", "П’ять хвилин", "Пів години"], "answer": "Хвилину"}, {"question_ua": "З чим їсти млинці?", "options": ["З джемом, медом або шоколадом", "Із сиром і шинкою", "З рибою"], "answer": "З джемом, медом або шоколадом"}]'::jsonb, 51, 0.824, 6, 'PUBLISHED', 'claude_reading_a1_v1')
