Pitajte prodavača na blagajni.',
        'ПОВЕРНЕННЯ Й ОБМІН ТОВАРУ
Товар можна повернути або обміняти протягом 14 днів.
Потрібні чек і оригінальна упаковка.
Одяг не можна носити до повернення.
Гроші повертаємо на картку або готівкою.
Запитайте продавця на касі.',
        '[{"form": "povrat", "lemma": "povrat", "ua": "повернення", "lesson": false}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "zamjena", "lemma": "zamjena", "ua": "обмін; заміна", "lesson": false}, {"form": "robe", "lemma": "roba", "ua": "товар", "lesson": false}, {"form": "robu", "lemma": "roba", "ua": "товар", "lesson": false}, {"form": "možete", "lemma": "moći", "ua": "могти", "lesson": true}, {"form": "vratiti", "lemma": "vratiti", "ua": "повернути", "lesson": true}, {"form": "ili", "lemma": "ili", "ua": "або", "lesson": true}, {"form": "zamijeniti", "lemma": "zamijeniti", "ua": "замінити", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "roku", "lemma": "rok", "ua": "дедлайн / термін", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "dana", "lemma": "dan", "ua": "день", "lesson": false}, {"form": "trebate", "lemma": "trebati", "ua": "потребувати", "lesson": true}, {"form": "račun", "lemma": "račun", "ua": "рахунок / чек", "lesson": true}, {"form": "originalno", "lemma": "originalan", "ua": "оригінальний", "lesson": false}, {"form": "pakiranje", "lemma": "pakiranje", "ua": "упаковка", "lesson": true}, {"form": "odjeću", "lemma": "odjeća", "ua": "одяг", "lesson": false}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true}, {"form": "smijete", "lemma": "smjeti", "ua": "сміти, мати дозвіл", "lesson": true}, {"form": "nositi", "lemma": "nositi", "ua": "носити / одягати", "lesson": true}, {"form": "prije", "lemma": "prije", "ua": "до; перед; раніше", "lesson": false}, {"form": "povrata", "lemma": "povrat", "ua": "повернення", "lesson": false}, {"form": "novac", "lemma": "novac", "ua": "гроші", "lesson": true}, {"form": "vraćamo", "lemma": "vratiti", "ua": "повернути", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "karticu", "lemma": "kartica", "ua": "банківська картка", "lesson": true}, {"form": "gotovini", "lemma": "gotovina", "ua": "готівка", "lesson": true}, {"form": "pitajte", "lemma": "pitati", "ua": "питати", "lesson": true}, {"form": "prodavača", "lemma": "prodavač", "ua": "продавець", "lesson": true}, {"form": "blagajni", "lemma": "blagajna", "ua": "каса", "lesson": true}]'::jsonb,
        '[{"question_ua": "За скільки днів можна повернути товар?", "options": ["14 днів", "7 днів", "30 днів"], "answer": "14 днів"}, {"question_ua": "Що потрібно для повернення?", "options": ["Чек і упаковка", "Паспорт", "Нічого"], "answer": "Чек і упаковка"}, {"question_ua": "Що не можна робити з одягом до повернення?", "options": ["Носити його", "Приміряти його", "Прати його"], "answer": "Носити його"}]'::jsonb, 35, 0.800, 10, 'PUBLISHED', 'claude_reading_a1_v1')
