insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-011', 'A1', 'message', 'shopping', 3, 'SMS від кур’єра', 'SMS od kurira',
        'Poštovani, Vaša pošiljka stiže danas između 14 i 17 sati. Kurir Vas zove prije dostave. Ako niste kod kuće, paket ostavljamo u paketomatu na adresi Ilica 25. Kod za otvaranje dobivate u novoj poruci. Za praćenje pošiljke posjetite našu stranicu.',
        'Шановний(-а), ваша посилка прибуде сьогодні між 14 і 17 годиною. Кур’єр подзвонить вам перед доставкою. Якщо вас немає вдома, посилку залишимо в поштоматі за адресою Іліца, 25. Код для відкриття отримаєте в новому повідомленні. Щоб відстежити посилку, відвідайте наш сайт.',
        '[{"form": "poštovani", "lemma": "poštovani", "ua": "шановний", "lesson": false}, {"form": "vaša", "lemma": "vaš", "ua": "ваш", "lesson": true}, {"form": "pošiljka", "lemma": "pošiljka", "ua": "поштове відправлення", "lesson": true}, {"form": "stiže", "lemma": "stići", "ua": "прибути / доїхати", "lesson": true}, {"form": "danas", "lemma": "danas", "ua": "сьогодні", "lesson": true}, {"form": "između", "lemma": "između", "ua": "між", "lesson": false}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "kurir", "lemma": "kurir", "ua": "кур’єр", "lesson": true}, {"form": "vas", "lemma": "vas", "ua": "вас; вам (займенник)", "lesson": false}, {"form": "zove", "lemma": "zvati", "ua": "дзвонити; кликати", "lesson": true}, {"form": "prije", "lemma": "prije", "ua": "до; перед; раніше", "lesson": false}, {"form": "dostave", "lemma": "dostava", "ua": "доставка", "lesson": true}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": false}, {"form": "niste", "lemma": "nije", "ua": "не є; немає (заперечення biti)", "lesson": false}, {"form": "kod", "lemma": "kod", "ua": "код", "lesson": false}, {"form": "kuće", "lemma": "kuća", "ua": "будинок; дім", "lesson": true}, {"form": "paket", "lemma": "paket", "ua": "посилка", "lesson": true}, {"form": "ostavljamo", "lemma": "ostaviti", "ua": "залишити", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "paketomatu", "lemma": "paketomat", "ua": "поштомат", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "adresi", "lemma": "adresa", "ua": "адреса", "lesson": true}, {"form": "ilica", "lemma": "Ilica", "ua": "Іліца (вулиця в Загребі)", "lesson": false}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false}, {"form": "otvaranje", "lemma": "otvaranje", "ua": "відкриття", "lesson": false}, {"form": "dobivate", "lemma": "dobiti", "ua": "отримати / здобути", "lesson": true}, {"form": "novoj", "lemma": "nov", "ua": "новий", "lesson": true}, {"form": "poruci", "lemma": "poruka", "ua": "повідомлення", "lesson": true}, {"form": "praćenje", "lemma": "praćenje pošiljke", "ua": "відстеження посилки", "lesson": true}, {"form": "pošiljke", "lemma": "pošiljka", "ua": "поштове відправлення", "lesson": true}, {"form": "posjetite", "lemma": "posjetiti", "ua": "відвідати", "lesson": true}, {"form": "našu", "lemma": "naš", "ua": "наш", "lesson": true}, {"form": "stranicu", "lemma": "stranica", "ua": "сторінка", "lesson": true}]'::jsonb,
        '[{"question_ua": "Коли прибуде посилка?", "options": ["Сьогодні між 14 і 17", "Завтра вранці", "У понеділок"], "answer": "Сьогодні між 14 і 17"}, {"question_ua": "Що буде, якщо вас немає вдома?", "options": ["Посилку залишать у поштоматі", "Посилку повернуть", "Кур’єр прийде завтра"], "answer": "Посилку залишать у поштоматі"}, {"question_ua": "Як отримати код?", "options": ["У новому повідомленні", "У кур’єра", "На пошті"], "answer": "У новому повідомленні"}]'::jsonb, 37, 0.919, 11, 'PUBLISHED', 'claude_reading_a1_v1')
on conflict (code) do nothing;
insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-012', 'A1', 'chat', 'shopping', 3, 'Яку куртку купити?', 'Koju jaknu kupiti?',
        'Oksana: Trebam zimsku jaknu za sina. Imaš li ideju?
Marija: Probaj u centru, tamo je sada sniženje.
Oksana: Vidim dvije jakne. Plava je jeftinija, a crna je toplija.
Marija: Uzmi topliju! Zima u Zagrebu je hladna.
Oksana: Imaš pravo. Uzimam crnu i nove rukavice.',
        'Оксана: Мені потрібна зимова куртка для сина. Маєш ідею?
Марія: Спробуй у центрі, там зараз розпродаж.
Оксана: Бачу дві куртки. Синя дешевша, а чорна тепліша.
Марія: Бери теплішу! Зима в Загребі холодна.
Оксана: Маєш рацію. Беру чорну і нові рукавички.',
        '[{"form": "oksana", "lemma": "Oksana", "ua": "Оксана (ім’я)", "lesson": false}, {"form": "trebam", "lemma": "trebati", "ua": "потребувати", "lesson": true}, {"form": "zimsku", "lemma": "zimski", "ua": "зимовий", "lesson": false}, {"form": "jaknu", "lemma": "jakna", "ua": "куртка", "lesson": true}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false}, {"form": "sina", "lemma": "sin", "ua": "син", "lesson": true}, {"form": "imaš", "lemma": "imati", "ua": "мати", "lesson": true}, {"form": "li", "lemma": "li", "ua": "чи (питальна частка)", "lesson": false}, {"form": "ideju", "lemma": "ideja", "ua": "ідея", "lesson": false}, {"form": "marija", "lemma": "Marija", "ua": "Марія (ім’я)", "lesson": false}, {"form": "probaj", "lemma": "probati", "ua": "приміряти / спробувати", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "centru", "lemma": "centar", "ua": "центр", "lesson": true}, {"form": "tamo", "lemma": "tamo", "ua": "там", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "sada", "lemma": "sada", "ua": "зараз", "lesson": false}, {"form": "sniženje", "lemma": "sniženje", "ua": "розпродаж; знижка", "lesson": false}, {"form": "vidim", "lemma": "vidjeti", "ua": "бачити", "lesson": false}, {"form": "dvije", "lemma": "dva", "ua": "два", "lesson": true}, {"form": "jakne", "lemma": "jakna", "ua": "куртка", "lesson": true}, {"form": "plava", "lemma": "plav", "ua": "синій / блакитний", "lesson": true}, {"form": "jeftinija", "lemma": "jeftin", "ua": "дешевий", "lesson": true}, {"form": "a", "lemma": "a", "ua": "а; і", "lesson": false}, {"form": "crna", "lemma": "crn", "ua": "чорний", "lesson": true}, {"form": "toplija", "lemma": "topao", "ua": "теплий", "lesson": true}, {"form": "uzmi", "lemma": "uzeti", "ua": "взяти", "lesson": true}, {"form": "topliju", "lemma": "topao", "ua": "теплий", "lesson": true}, {"form": "zima", "lemma": "zima", "ua": "зима", "lesson": true}, {"form": "zagrebu", "lemma": "Zagreb", "ua": "Загреб", "lesson": false}, {"form": "hladna", "lemma": "hladan", "ua": "холодний", "lesson": true}, {"form": "pravo", "lemma": "imati pravo", "ua": "мати рацію", "lesson": false}, {"form": "uzimam", "lemma": "uzimati", "ua": "брати; приймати (ліки)", "lesson": true}, {"form": "crnu", "lemma": "crn", "ua": "чорний", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "nove", "lemma": "nov", "ua": "новий", "lesson": true}, {"form": "rukavice", "lemma": "rukavice", "ua": "рукавички", "lesson": true}]'::jsonb,
        '[{"question_ua": "Для кого куртка?", "options": ["Для сина", "Для чоловіка", "Для Марії"], "answer": "Для сина"}, {"question_ua": "Яка куртка дешевша?", "options": ["Синя", "Чорна", "Обидві однакові"], "answer": "Синя"}, {"question_ua": "Що ще купує Оксана?", "options": ["Рукавички", "Шапку", "Черевики"], "answer": "Рукавички"}]'::jsonb, 44, 0.909, 12, 'PUBLISHED', 'claude_reading_a1_v1')
