values ('RD-A1-013', 'A1', 'notice', 'transport', 4, 'Зміна маршруту трамвая', 'Promjena linije tramvaja',
        'OBAVIJEST PUTNICIMA
Zbog radova na cesti tramvaj broj 6 od ponedjeljka ne vozi do Glavnog kolodvora.
Putnici mogu presjedati na autobus broj 109 na stanici Trg bana Jelačića.
Karta vrijedi za tramvaj i za autobus.
Hvala na razumijevanju!',
        'ОГОЛОШЕННЯ ДЛЯ ПАСАЖИРІВ
Через дорожні роботи трамвай номер 6 з понеділка не їздить до Головного вокзалу.
Пасажири можуть пересісти на автобус номер 109 на зупинці «Площа бана Єлачича».
Квиток дійсний і для трамвая, і для автобуса.
Дякуємо за розуміння!',
        '[{"form": "obavijest", "lemma": "obavijest", "ua": "оголошення; повідомлення", "lesson": false}, {"form": "putnicima", "lemma": "putnik", "ua": "пасажир / мандрівник", "lesson": true}, {"form": "zbog", "lemma": "zbog", "ua": "через (причина)", "lesson": false}, {"form": "radova", "lemma": "radovi", "ua": "роботи (ремонтні)", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "cesti", "lemma": "cesta", "ua": "дорога", "lesson": false}, {"form": "tramvaj", "lemma": "tramvaj", "ua": "трамвай", "lesson": true}, {"form": "broj", "lemma": "broj", "ua": "номер / число", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "ponedjeljka", "lemma": "ponedjeljak", "ua": "понеділок", "lesson": true}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true}, {"form": "vozi", "lemma": "voziti", "ua": "водити (авто) / везти", "lesson": true}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "glavnog", "lemma": "glavni", "ua": "головний", "lesson": false}, {"form": "kolodvora", "lemma": "kolodvor", "ua": "вокзал", "lesson": true}, {"form": "putnici", "lemma": "putnik", "ua": "пасажир / мандрівник", "lesson": true}, {"form": "mogu", "lemma": "moći", "ua": "могти", "lesson": true}, {"form": "presjedati", "lemma": "presjedati", "ua": "робити пересадку", "lesson": true}, {"form": "autobus", "lemma": "autobus", "ua": "автобус", "lesson": true}, {"form": "stanici", "lemma": "stanica", "ua": "зупинка / станція", "lesson": true}, {"form": "trg", "lemma": "trg", "ua": "площа", "lesson": true}, {"form": "bana", "lemma": "ban", "ua": "бан (титул; «Trg bana Jelačića» — площа в Загребі)", "lesson": false}, {"form": "jelačića", "lemma": "Jelačić", "ua": "Єлачич (прізвище; «Trg bana Jelačića» — площа в Загребі)", "lesson": false}, {"form": "karta", "lemma": "karta", "ua": "квиток / карта", "lesson": true}, {"form": "vrijedi", "lemma": "vrijediti", "ua": "бути дійсним; коштувати", "lesson": false}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "hvala", "lemma": "hvala", "ua": "дякую", "lesson": true}, {"form": "razumijevanju", "lemma": "razumijevanje", "ua": "розуміння", "lesson": false}]'::jsonb,
        '[{"question_ua": "Чому трамвай змінює маршрут?", "options": ["Через дорожні роботи", "Через снігопад", "Через свято"], "answer": "Через дорожні роботи"}, {"question_ua": "На який автобус можна пересісти?", "options": ["109", "6", "25"], "answer": "109"}, {"question_ua": "Чи потрібен новий квиток на автобус?", "options": ["Ні, квиток дійсний", "Так, треба купити", "Так, у водія"], "answer": "Ні, квиток дійсний"}]'::jsonb, 36, 0.861, 13, 'PUBLISHED', 'claude_reading_a1_v1')
