values ('RD-A1-014', 'A1', 'instruction', 'transport', 4, 'Як купити квиток в автоматі', 'Kako kupiti kartu na automatu',
        '1. Odaberite jezik.
2. Odaberite kartu: jednosmjernu ili povratnu.
3. Upišite broj putnika.
4. Platite karticom ili kovanicama.
5. Uzmite kartu i ostatak novca.
Karta vrijedi 90 minuta. Poništite je u tramvaju ili autobusu.',
        '1. Виберіть мову.
2. Виберіть квиток: в один бік чи туди й назад.
3. Введіть кількість пасажирів.
4. Заплатіть карткою або монетами.
5. Заберіть квиток і решту.
Квиток дійсний 90 хвилин. Прокомпостуйте його в трамваї чи автобусі.',
        '[{"form": "odaberite", "lemma": "odabrati", "ua": "вибрати", "lesson": false}, {"form": "jezik", "lemma": "jezik", "ua": "мова", "lesson": true}, {"form": "kartu", "lemma": "karta", "ua": "квиток / карта", "lesson": true}, {"form": "jednosmjernu", "lemma": "jednosmjerna karta", "ua": "квиток в один бік", "lesson": true}, {"form": "ili", "lemma": "ili", "ua": "або", "lesson": true}, {"form": "povratnu", "lemma": "povratna karta", "ua": "квиток туди і назад", "lesson": true}, {"form": "upišite", "lemma": "upisati", "ua": "записати (в садок, школу); вписати", "lesson": true}, {"form": "broj", "lemma": "broj", "ua": "номер / число", "lesson": true}, {"form": "putnika", "lemma": "putnik", "ua": "пасажир / мандрівник", "lesson": true}, {"form": "platite", "lemma": "platiti", "ua": "заплатити", "lesson": true}, {"form": "karticom", "lemma": "kartica", "ua": "банківська картка", "lesson": true}, {"form": "kovanicama", "lemma": "kovanica", "ua": "монета", "lesson": false}, {"form": "uzmite", "lemma": "uzeti", "ua": "взяти", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "ostatak", "lemma": "ostatak", "ua": "залишок; решта", "lesson": false}, {"form": "novca", "lemma": "novac", "ua": "гроші", "lesson": true}, {"form": "karta", "lemma": "karta", "ua": "квиток / карта", "lesson": true}, {"form": "vrijedi", "lemma": "vrijediti", "ua": "бути дійсним; коштувати", "lesson": false}, {"form": "minuta", "lemma": "minuta", "ua": "хвилина", "lesson": true}, {"form": "poništite", "lemma": "poništiti", "ua": "прокомпостувати; скасувати", "lesson": false}, {"form": "je", "lemma": "nju", "ua": "її (займенник)", "lesson": false}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "tramvaju", "lemma": "tramvaj", "ua": "трамвай", "lesson": true}, {"form": "autobusu", "lemma": "autobus", "ua": "автобус", "lesson": true}]'::jsonb,
        '[{"question_ua": "Скільки часу дійсний квиток?", "options": ["90 хвилин", "Один день", "30 хвилин"], "answer": "90 хвилин"}, {"question_ua": "Як можна заплатити?", "options": ["Карткою або монетами", "Лише готівкою", "Лише карткою"], "answer": "Карткою або монетами"}, {"question_ua": "Що треба зробити з квитком у трамваї?", "options": ["Прокомпостувати", "Віддати водієві", "Нічого"], "answer": "Прокомпостувати"}]'::jsonb, 28, 0.786, 14, 'PUBLISHED', 'claude_reading_a1_v1')
