values ('RD-A1-016', 'A1', 'news', 'travel', 4, 'Літній розклад поромів', 'Ljetni red plovidbe',
        'Od lipnja do rujna trajekti iz Splita za Brač voze svaki sat, od pet ujutro do ponoći. Ljeti je velika gužva, zato putnici trebaju kupiti karte na internetu. Auti moraju biti u luci pola sata prije polaska. Pješaci mogu doći petnaest minuta prije.',
        'З червня до вересня пороми зі Спліта на Брач ходять щогодини, з п’ятої ранку до опівночі. Улітку велика черга, тому пасажирам треба купувати квитки в інтернеті. Автомобілі мають бути в порту за пів години до відправлення. Пішоходи можуть прийти за п’ятнадцять хвилин до відправлення.',
        '[{"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "lipnja", "lemma": "lipanj", "ua": "червень", "lesson": true}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "rujna", "lemma": "rujan", "ua": "вересень", "lesson": true}, {"form": "trajekti", "lemma": "trajekt", "ua": "пором", "lesson": true}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": false}, {"form": "splita", "lemma": "Split", "ua": "Спліт (місто)", "lesson": false}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false}, {"form": "brač", "lemma": "Brač", "ua": "Брач (острів)", "lesson": false}, {"form": "voze", "lemma": "voziti", "ua": "водити (авто) / везти", "lesson": true}, {"form": "svaki", "lemma": "svaki", "ua": "кожен", "lesson": false}, {"form": "sat", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "pet", "lemma": "pet", "ua": "п''ять", "lesson": true}, {"form": "ujutro", "lemma": "ujutro", "ua": "вранці", "lesson": true}, {"form": "ponoći", "lemma": "ponoć", "ua": "північ (час)", "lesson": true}, {"form": "ljeti", "lemma": "ljeti", "ua": "улітку", "lesson": false}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "velika", "lemma": "velik", "ua": "великий", "lesson": true}, {"form": "gužva", "lemma": "gužva", "ua": "затор; тиснява", "lesson": true}, {"form": "zato", "lemma": "zato", "ua": "тому", "lesson": false}, {"form": "putnici", "lemma": "putnik", "ua": "пасажир / мандрівник", "lesson": true}, {"form": "trebaju", "lemma": "trebati", "ua": "потребувати", "lesson": true}, {"form": "kupiti", "lemma": "kupiti", "ua": "купити", "lesson": true}, {"form": "karte", "lemma": "karta", "ua": "квиток / карта", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "internetu", "lemma": "internet", "ua": "інтернет", "lesson": true}, {"form": "auti", "lemma": "auto", "ua": "автомобіль", "lesson": true}, {"form": "moraju", "lemma": "morati", "ua": "мусити / бути зобов''язаним", "lesson": true}, {"form": "biti", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "luci", "lemma": "luka", "ua": "порт", "lesson": true}, {"form": "pola", "lemma": "pola", "ua": "половина", "lesson": true}, {"form": "sata", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "prije", "lemma": "prije", "ua": "до; перед; раніше", "lesson": false}, {"form": "polaska", "lemma": "polazak", "ua": "відправлення", "lesson": true}, {"form": "pješaci", "lemma": "pješak", "ua": "пішохід", "lesson": true}, {"form": "mogu", "lemma": "moći", "ua": "могти", "lesson": true}, {"form": "doći", "lemma": "doći", "ua": "прийти", "lesson": true}, {"form": "petnaest", "lemma": "petnaest", "ua": "п''ятнадцять", "lesson": true}, {"form": "minuta", "lemma": "minuta", "ua": "хвилина", "lesson": true}]'::jsonb,
        '[{"question_ua": "Як часто влітку ходять пороми на Брач?", "options": ["Щогодини", "Двічі на день", "Щопівгодини"], "answer": "Щогодини"}, {"question_ua": "Де краще купувати квитки?", "options": ["В інтернеті", "На поромі", "У водія"], "answer": "В інтернеті"}, {"question_ua": "Коли авто має бути в порту?", "options": ["За пів години до відправлення", "За п’ять хвилин", "За дві години"], "answer": "За пів години до відправлення"}]'::jsonb, 43, 0.977, 16, 'PUBLISHED', 'claude_reading_a1_v1')
