values ('RD-A1-017', 'A1', 'ad', 'housing', 5, 'Оголошення: квартира в оренду', 'Oglas: stan za najam',
        'IZNAJMLJUJEM STAN
Dvosoban stan, 55 m², drugi kat, Trešnjevka.
Namješten, s balkonom i perilicom rublja.
Najamnina: 650 € mjesečno + režije.
Polog: jedna najamnina.
Blizu tramvaja, škole i trgovine.
Kućni ljubimci nisu dopušteni.
Zovite na 091 234 5678.',
        'ЗДАЮ КВАРТИРУ
Двокімнатна квартира, 55 м², другий поверх, Трешнєвка.
Мебльована, з балконом і пральною машиною.
Орендна плата: 650 € на місяць + комунальні.
Застава: одна орендна плата.
Поруч трамвай, школа й магазин.
Домашні тварини заборонені.
Телефонуйте на 091 234 5678.',
        '[{"form": "iznajmljujem", "lemma": "iznajmiti", "ua": "орендувати / здати в оренду", "lesson": true}, {"form": "stan", "lemma": "stan", "ua": "квартира", "lesson": true}, {"form": "dvosoban", "lemma": "dvosoban", "ua": "двокімнатний", "lesson": false}, {"form": "m", "lemma": "m", "ua": "м (метр)", "lesson": false}, {"form": "drugi", "lemma": "drugi", "ua": "другий; інший", "lesson": false}, {"form": "kat", "lemma": "kat", "ua": "поверх", "lesson": true}, {"form": "trešnjevka", "lemma": "Trešnjevka", "ua": "Трешнєвка (район Загреба)", "lesson": false}, {"form": "namješten", "lemma": "namješten", "ua": "мебльований", "lesson": true}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "balkonom", "lemma": "balkon", "ua": "балкон", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "perilicom", "lemma": "perilica", "ua": "пральна машина", "lesson": true}, {"form": "rublja", "lemma": "rublje", "ua": "білизна (для прання)", "lesson": true}, {"form": "najamnina", "lemma": "najamnina", "ua": "орендна плата / квартплата", "lesson": true}, {"form": "mjesečno", "lemma": "mjesečno", "ua": "щомісяця; на місяць", "lesson": true}, {"form": "režije", "lemma": "režije", "ua": "комунальні послуги / рахунки", "lesson": true}, {"form": "polog", "lemma": "polog", "ua": "застава / депозит", "lesson": true}, {"form": "jedna", "lemma": "jedan", "ua": "один", "lesson": true}, {"form": "blizu", "lemma": "blizu", "ua": "поруч / близько", "lesson": true}, {"form": "tramvaja", "lemma": "tramvaj", "ua": "трамвай", "lesson": true}, {"form": "škole", "lemma": "škola", "ua": "школа", "lesson": true}, {"form": "trgovine", "lemma": "trgovina", "ua": "магазин / крамниця", "lesson": true}, {"form": "kućni", "lemma": "kućni ljubimac", "ua": "домашній улюбленець", "lesson": true}, {"form": "ljubimci", "lemma": "kućni ljubimac", "ua": "домашній улюбленець", "lesson": true}, {"form": "nisu", "lemma": "nije", "ua": "не є; немає (заперечення biti)", "lesson": false}, {"form": "dopušteni", "lemma": "dopušteno", "ua": "дозволено", "lesson": true}, {"form": "zovite", "lemma": "zvati", "ua": "дзвонити; кликати", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}]'::jsonb,
        '[{"question_ua": "Скільки кімнат у квартирі?", "options": ["Дві", "Одна", "Три"], "answer": "Дві"}, {"question_ua": "Що входить у ціну 650 €?", "options": ["Лише оренда, комунальні окремо", "Оренда й комунальні", "Оренда й інтернет"], "answer": "Лише оренда, комунальні окремо"}, {"question_ua": "Чи можна жити з собакою?", "options": ["Ні", "Так", "Лише з маленькою"], "answer": "Ні"}]'::jsonb, 31, 0.935, 17, 'PUBLISHED', 'claude_reading_a1_v1')
