values ('RD-A1-018', 'A1', 'notice', 'housing', 5, 'У будинку не буде води', 'Obavijest: bez vode',
        'OBAVIJEST STANARIMA
U srijedu, 15. listopada, od 9 do 14 sati zgrada nema vode zbog popravka cijevi u podrumu.
Molimo stanare da pripreme vodu za piće i kuhanje.
Ako imate pitanja, zovite upravitelja zgrade.
Hvala na razumijevanju!',
        'ОГОЛОШЕННЯ ДЛЯ МЕШКАНЦІВ
У середу, 15 жовтня, з 9 до 14 години в будинку не буде води через ремонт труб у підвалі.
Просимо мешканців підготувати воду для пиття й готування.
Якщо у вас є питання, телефонуйте управителю будинку.
Дякуємо за розуміння!',
        '[{"form": "obavijest", "lemma": "obavijest", "ua": "оголошення; повідомлення", "lesson": false}, {"form": "stanarima", "lemma": "stanar", "ua": "мешканець", "lesson": false}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "srijedu", "lemma": "srijeda", "ua": "середа", "lesson": true}, {"form": "listopada", "lemma": "listopad", "ua": "жовтень", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "zgrada", "lemma": "zgrada", "ua": "будівля", "lesson": true}, {"form": "nema", "lemma": "nema", "ua": "немає", "lesson": false}, {"form": "vode", "lemma": "voda", "ua": "вода", "lesson": true}, {"form": "zbog", "lemma": "zbog", "ua": "через (причина)", "lesson": false}, {"form": "popravka", "lemma": "popravak", "ua": "ремонт", "lesson": true}, {"form": "cijevi", "lemma": "cijev", "ua": "труба", "lesson": false}, {"form": "podrumu", "lemma": "podrum", "ua": "підвал", "lesson": true}, {"form": "molimo", "lemma": "molim", "ua": "Прошу / Будь ласка / Що (ви сказали)?", "lesson": true}, {"form": "stanare", "lemma": "stanar", "ua": "мешканець", "lesson": false}, {"form": "da", "lemma": "da", "ua": "так / що", "lesson": true}, {"form": "pripreme", "lemma": "pripremiti", "ua": "підготувати", "lesson": false}, {"form": "vodu", "lemma": "voda", "ua": "вода", "lesson": true}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false}, {"form": "piće", "lemma": "piće", "ua": "напій", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "kuhanje", "lemma": "kuhanje", "ua": "готування (їжі)", "lesson": false}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": false}, {"form": "imate", "lemma": "imati", "ua": "мати", "lesson": true}, {"form": "pitanja", "lemma": "pitanje", "ua": "питання", "lesson": false}, {"form": "zovite", "lemma": "zvati", "ua": "дзвонити; кликати", "lesson": true}, {"form": "upravitelja", "lemma": "upravitelj zgrade", "ua": "управитель будинку", "lesson": true}, {"form": "zgrade", "lemma": "zgrada", "ua": "будівля", "lesson": true}, {"form": "hvala", "lemma": "hvala", "ua": "дякую", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "razumijevanju", "lemma": "razumijevanje", "ua": "розуміння", "lesson": false}]'::jsonb,
        '[{"question_ua": "Чому не буде води?", "options": ["Ремонт труб у підвалі", "Борг за воду", "Прибирання"], "answer": "Ремонт труб у підвалі"}, {"question_ua": "Скільки годин не буде води?", "options": ["П’ять", "Дві", "Цілий день"], "answer": "П’ять"}, {"question_ua": "Кому дзвонити з питаннями?", "options": ["Управителю будинку", "Сусідові", "Поліції"], "answer": "Управителю будинку"}]'::jsonb, 34, 0.794, 18, 'PUBLISHED', 'claude_reading_a1_v1')
