і", "lesson": false}, {"form": "smo", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false}, {"form": "kuće", "lemma": "kuća", "ua": "будинок; дім", "lesson": true}, {"form": "cijeli", "lemma": "cijel", "ua": "цілий; весь", "lesson": false}, {"form": "hvala", "lemma": "hvala", "ua": "дякую", "lesson": true}, {"form": "olena", "lemma": "Olena", "ua": "Олена (ім’я)", "lesson": false}, {"form": "kovalenko", "lemma": "Kovalenko", "ua": "Коваленко (прізвище)", "lesson": false}, {"form": "stan", "lemma": "stan", "ua": "квартира", "lesson": true}, {"form": "broj", "lemma": "broj", "ua": "номер / число", "lesson": true}]'::jsonb,
