        '[{"question_ua": "Куди викидати пляшку зі скла?", "options": ["У зелений контейнер", "У жовтий", "У синій"], "answer": "У зелений контейнер"}, {"question_ua": "Що кидати в синій контейнер?", "options": ["Папір і картон", "Залишки їжі", "Пластик"], "answer": "Папір і картон"}, {"question_ua": "Коли виносити сміття?", "options": ["Увечері, до восьмої", "Уранці в неділю", "Будь-коли"], "answer": "Увечері, до восьмої"}]'::jsonb, 35, 0.771, 20, 'PUBLISHED', 'claude_reading_a1_v1')
