values ('RD-A1-021', 'A1', 'ad', 'work', 6, 'Вакансія: покоївка в готелі', 'Oglas: sobarica u hotelu',
        'HOTEL MARINA TRAŽI SOBARICU
Posao: čišćenje soba i kupaonica.
Uvjeti: sezonski posao od svibnja do listopada, puno radno vrijeme.
Satnica: 7 € neto. Smještaj i hrana su besplatni.
Iskustvo nije potrebno, znanje engleskog je prednost.
Životopis pošaljite na posao@hotelmarina.hr.',
        'ГОТЕЛЬ «МАРИНА» ШУКАЄ ПОКОЇВКУ
Робота: прибирання номерів і ванних кімнат.
Умови: сезонна робота з травня до жовтня, повний робочий день.
Погодинна оплата: 7 € чистими. Житло й харчування безкоштовні.
Досвід не потрібен, знання англійської — перевага.
Резюме надсилайте на posao@hotelmarina.hr.',
        '[{"form": "hotel", "lemma": "hotel", "ua": "готель", "lesson": true}, {"form": "marina", "lemma": "Marina", "ua": "«Марина» (назва готелю)", "lesson": false}, {"form": "traži", "lemma": "tražiti", "ua": "шукати", "lesson": true}, {"form": "sobaricu", "lemma": "sobarica", "ua": "покоївка", "lesson": true}, {"form": "posao", "lemma": "posao", "ua": "робота / справа", "lesson": true}, {"form": "čišćenje", "lemma": "čišćenje", "ua": "прибирання", "lesson": false}, {"form": "soba", "lemma": "soba", "ua": "кімната", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "kupaonica", "lemma": "kupaonica", "ua": "ванна кімната", "lesson": true}, {"form": "uvjeti", "lemma": "uvjet", "ua": "умова", "lesson": true}, {"form": "sezonski", "lemma": "sezonski", "ua": "сезонний", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "svibnja", "lemma": "svibanj", "ua": "травень", "lesson": true}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "listopada", "lemma": "listopad", "ua": "жовтень", "lesson": true}, {"form": "puno", "lemma": "puno", "ua": "багато", "lesson": true}, {"form": "radno", "lemma": "radno vrijeme", "ua": "робочий час", "lesson": true}, {"form": "vrijeme", "lemma": "vrijeme", "ua": "погода / час", "lesson": true}, {"form": "satnica", "lemma": "satnica", "ua": "погодинна оплата", "lesson": true}, {"form": "neto", "lemma": "neto", "ua": "нетто (після податків)", "lesson": true}, {"form": "smještaj", "lemma": "smještaj", "ua": "житло / розміщення", "lesson": true}, {"form": "hrana", "lemma": "hrana", "ua": "їжа", "lesson": true}, {"form": "su", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "besplatni", "lemma": "besplatan", "ua": "безкоштовний", "lesson": false}, {"form": "iskustvo", "lemma": "iskustvo", "ua": "досвід", "lesson": true}, {"form": "nije", "lemma": "nije", "ua": "не є; немає (заперечення biti)", "lesson": false}, {"form": "potrebno", "lemma": "potreban", "ua": "потрібний", "lesson": false}, {"form": "znanje", "lemma": "znanje", "ua": "знання", "lesson": false}, {"form": "engleskog", "lemma": "engleski", "ua": "англійська (мова)", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "prednost", "lemma": "prednost", "ua": "перевага", "lesson": true}, {"form": "životopis", "lemma": "životopis", "ua": "резюме", "lesson": true}, {"form": "pošaljite", "lemma": "poslati", "ua": "надіслати / відправити", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}]'::jsonb,
        '[{"question_ua": "Яка це робота?", "options": ["Сезонна", "Постійна", "Лише у вихідні"], "answer": "Сезонна"}, {"question_ua": "Що безкоштовне?", "options": ["Житло й харчування", "Транспорт", "Курси англійської"], "answer": "Житло й харчування"}, {"question_ua": "Чи потрібен досвід?", "options": ["Ні", "Так, два роки", "Так, у готелі"], "answer": "Ні"}]'::jsonb, 36, 0.889, 21, 'PUBLISHED', 'claude_reading_a1_v1')
