values ('RD-A1-022', 'A1', 'email', 'work', 6, 'Лист від роботодавця', 'Mail od poslodavca',
        'Poštovani gospodine Melnyk,
dobro došli u našu tvrtku! Vaš prvi radni dan je u ponedjeljak. Dođite u osam sati na ulaz B. Na recepciji Vas čeka voditeljica smjene, gospođa Babić. Ponesite osobnu iskaznicu, OIB i broj računa u banci. Radnu odjeću dobivate prvi dan.
Lijep pozdrav,
Ana Perić, ured za ljudske resurse',
        'Шановний пане Мельник,
ласкаво просимо до нашої компанії! Ваш перший робочий день — у понеділок. Приходьте о восьмій годині до входу B. На рецепції на вас чекатиме керівниця зміни, пані Бабич. Візьміть із собою посвідчення особи, OIB і номер банківського рахунку. Робочий одяг отримаєте першого дня.
З повагою,
Ана Перич, відділ кадрів',
        '[{"form": "poštovani", "lemma": "poštovani", "ua": "шановний", "lesson": false}, {"form": "gospodine", "lemma": "gospodin", "ua": "пан", "lesson": true}, {"form": "melnyk", "lemma": "Melnyk", "ua": "Мельник (прізвище)", "lesson": false}, {"form": "dobro", "lemma": "dobro", "ua": "добре", "lesson": true}, {"form": "došli", "lemma": "doći", "ua": "прийти", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "našu", "lemma": "naš", "ua": "наш", "lesson": true}, {"form": "tvrtku", "lemma": "tvrtka", "ua": "компанія / фірма", "lesson": true}, {"form": "vaš", "lemma": "vaš", "ua": "ваш", "lesson": true}, {"form": "prvi", "lemma": "prvi", "ua": "перший", "lesson": true}, {"form": "radni", "lemma": "radni", "ua": "робочий", "lesson": false}, {"form": "dan", "lemma": "dan", "ua": "день", "lesson": false}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "ponedjeljak", "lemma": "ponedjeljak", "ua": "понеділок", "lesson": true}, {"form": "dođite", "lemma": "doći", "ua": "прийти", "lesson": true}, {"form": "osam", "lemma": "osam", "ua": "вісім", "lesson": true}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "ulaz", "lemma": "ulaz", "ua": "вхід; під’їзд", "lesson": true}, {"form": "b", "lemma": "B", "ua": "B (літера, позначення входу)", "lesson": false}, {"form": "recepciji", "lemma": "recepcija", "ua": "рецепція", "lesson": true}, {"form": "vas", "lemma": "vas", "ua": "вас; вам (займенник)", "lesson": false}, {"form": "čeka", "lemma": "čekati", "ua": "чекати", "lesson": true}, {"form": "voditeljica", "lemma": "voditelj", "ua": "керівник, ведучий", "lesson": true}, {"form": "smjene", "lemma": "smjena", "ua": "зміна (на роботі)", "lesson": true}, {"form": "gospođa", "lemma": "gospođa", "ua": "пані", "lesson": true}, {"form": "babić", "lemma": "Babić", "ua": "Бабич (прізвище)", "lesson": false}, {"form": "ponesite", "lemma": "ponijeti", "ua": "взяти із собою", "lesson": true}, {"form": "osobnu", "lemma": "osobna iskaznica", "ua": "посвідчення особи", "lesson": true}, {"form": "iskaznicu", "lemma": "iskaznica", "ua": "посвідчення; картка", "lesson": false}, {"form": "oib", "lemma": "OIB", "ua": "Ідентифікаційний номер (OIB)", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "broj", "lemma": "broj", "ua": "номер / число", "lesson": true}, {"form": "računa", "lemma": "račun", "ua": "рахунок / чек", "lesson": true}, {"form": "banci", "lemma": "banka", "ua": "банк", "lesson": true}, {"form": "radnu", "lemma": "radna odjeća", "ua": "робочий одяг", "lesson": true}, {"form": "odjeću", "lemma": "odjeća", "ua": "одяг", "lesson": false}, {"form": "dobivate", "lemma": "dobiti", "ua": "отримати / здобути", "lesson": true}, {"form": "lijep", "lemma": "lijep", "ua": "красивий", "lesson": true}, {"form": "pozdrav", "lemma": "pozdrav", "ua": "привіт; вітання", "lesson": false}, {"form": "ana", "lemma": "Ana", "ua": "Ана (ім’я)", "lesson": false}, {"form": "perić", "lemma": "Perić", "ua": "Перич (прізвище)", "lesson": false}, {"form": "ured", "lemma": "ured", "ua": "офіс / кабінет", "lesson": true}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false}, {"form": "ljudske", "lemma": "ljudski resursi", "ua": "людські ресурси (відділ кадрів)", "lesson": false}, {"form": "resurse", "lemma": "ljudski resursi", "ua": "людські ресурси (відділ кадрів)", "lesson": false}]'::jsonb,
