values ('RD-A1-023', 'A1', 'notice', 'work', 6, 'Розклад змін', 'Raspored smjena',
        'RASPORED SMJENA – SKLADIŠTE
Jutarnja smjena: od 6 do 14 sati.
Popodnevna smjena: od 14 do 22 sata.
Pauza: 30 minuta, u kantini na prvom katu.
Zamjenu smjene dogovorite s voditeljem najkasnije dan prije.
Bolovanje javite voditelju prije početka smjene.',
        'РОЗКЛАД ЗМІН – СКЛАД
Ранкова зміна: з 6 до 14 години.
Денна зміна: з 14 до 22 години.
Перерва: 30 хвилин, у їдальні на першому поверсі.
Обмін змінами погоджуйте з керівником не пізніше ніж за день.
Про лікарняний повідомте керівника до початку зміни.',
        '[{"form": "raspored", "lemma": "raspored", "ua": "розклад", "lesson": true}, {"form": "smjena", "lemma": "smjena", "ua": "зміна (на роботі)", "lesson": true}, {"form": "skladište", "lemma": "skladište", "ua": "склад", "lesson": true}, {"form": "jutarnja", "lemma": "jutarnji", "ua": "ранковий", "lesson": false}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "popodnevna", "lemma": "popodnevni", "ua": "післяобідній; денний (зміна)", "lesson": false}, {"form": "sata", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "pauza", "lemma": "pauza", "ua": "перерва", "lesson": true}, {"form": "minuta", "lemma": "minuta", "ua": "хвилина", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "kantini", "lemma": "kantina", "ua": "їдальня (на роботі)", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "prvom", "lemma": "prvi", "ua": "перший", "lesson": true}, {"form": "katu", "lemma": "kat", "ua": "поверх", "lesson": true}, {"form": "zamjenu", "lemma": "zamjena", "ua": "обмін; заміна", "lesson": false}, {"form": "smjene", "lemma": "smjena", "ua": "зміна (на роботі)", "lesson": true}, {"form": "dogovorite", "lemma": "dogovoriti se", "ua": "домовитися", "lesson": true}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "voditeljem", "lemma": "voditelj", "ua": "керівник, ведучий", "lesson": true}, {"form": "najkasnije", "lemma": "najkasnije", "ua": "найпізніше", "lesson": false}, {"form": "dan", "lemma": "dan", "ua": "день", "lesson": false}, {"form": "prije", "lemma": "prije", "ua": "до; перед; раніше", "lesson": false}, {"form": "bolovanje", "lemma": "bolovanje", "ua": "лікарняний", "lesson": true}, {"form": "javite", "lemma": "javiti se", "ua": "обізватися; відповісти (на дзвінок); зголоситися", "lesson": true}, {"form": "voditelju", "lemma": "voditelj", "ua": "керівник, ведучий", "lesson": true}, {"form": "početka", "lemma": "početak", "ua": "початок", "lesson": false}]'::jsonb,
        '[{"question_ua": "Коли починається ранкова зміна?", "options": ["О 6", "О 8", "О 14"], "answer": "О 6"}, {"question_ua": "Скільки триває перерва?", "options": ["30 хвилин", "15 хвилин", "Годину"], "answer": "30 хвилин"}, {"question_ua": "Коли повідомити про лікарняний?", "options": ["До початку зміни", "Після зміни", "За тиждень"], "answer": "До початку зміни"}]'::jsonb, 34, 0.824, 23, 'PUBLISHED', 'claude_reading_a1_v1')
