insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-024', 'A1', 'story', 'work', 6, 'Оксана на роботі', 'Oksana na poslu',
        'Oksana radi kao njegovateljica. Svako jutro dolazi kod gospođe Marije. Gospođa Marija ima osamdeset godina i živi sama. Oksana joj kuha ručak, ide s njom u šetnju i daje joj lijekove. Gospođa Marija joj priča o Zagrebu, a Oksana uči nove riječi. Posao nije lak, ali Oksana ga voli.',
        'Оксана працює доглядальницею. Щоранку вона приходить до пані Марії. Пані Марії вісімдесят років, і вона живе сама. Оксана готує їй обід, ходить з нею на прогулянку й дає їй ліки. Пані Марія розповідає їй про Загреб, а Оксана вивчає нові слова. Робота не легка, але Оксана її любить.',
        '[{"form": "oksana", "lemma": "Oksana", "ua": "Оксана (ім’я)", "lesson": false}, {"form": "radi", "lemma": "raditi", "ua": "працювати, робити", "lesson": true}, {"form": "kao", "lemma": "kao", "ua": "як", "lesson": false}, {"form": "njegovateljica", "lemma": "njegovateljica", "ua": "доглядальниця", "lesson": true}, {"form": "svako", "lemma": "svaki", "ua": "кожен", "lesson": false}, {"form": "jutro", "lemma": "jutro", "ua": "ранок", "lesson": true}, {"form": "dolazi", "lemma": "dolaziti", "ua": "приходити", "lesson": true}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false}, {"form": "gospođe", "lemma": "gospođa", "ua": "пані", "lesson": true}, {"form": "marije", "lemma": "Marija", "ua": "Марія (ім’я)", "lesson": false}, {"form": "gospođa", "lemma": "gospođa", "ua": "пані", "lesson": true}, {"form": "marija", "lemma": "Marija", "ua": "Марія (ім’я)", "lesson": false}, {"form": "ima", "lemma": "imati", "ua": "мати", "lesson": true}, {"form": "osamdeset", "lemma": "osamdeset", "ua": "вісімдесят", "lesson": true}, {"form": "godina", "lemma": "godina", "ua": "рік", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "živi", "lemma": "živjeti", "ua": "жити", "lesson": true}, {"form": "sama", "lemma": "sam", "ua": "сама (одна)", "lesson": false}, {"form": "joj", "lemma": "joj", "ua": "їй (займенник)", "lesson": false}, {"form": "kuha", "lemma": "kuhati", "ua": "варити / готувати їжу", "lesson": true}, {"form": "ručak", "lemma": "ručak", "ua": "обід", "lesson": true}, {"form": "ide", "lemma": "ići", "ua": "іти, їхати", "lesson": true}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "njom", "lemma": "ona", "ua": "вона", "lesson": false}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "šetnju", "lemma": "šetnja", "ua": "прогулянка", "lesson": false}, {"form": "daje", "lemma": "davati", "ua": "давати", "lesson": false}, {"form": "lijekove", "lemma": "lijek", "ua": "ліки / медикамент", "lesson": true}, {"form": "priča", "lemma": "pričati", "ua": "розповідати; розмовляти", "lesson": true}, {"form": "o", "lemma": "o", "ua": "про", "lesson": false}, {"form": "zagrebu", "lemma": "Zagreb", "ua": "Загреб", "lesson": false}, {"form": "a", "lemma": "a", "ua": "а; і", "lesson": false}, {"form": "uči", "lemma": "učiti", "ua": "вчити (ся)", "lesson": true}, {"form": "nove", "lemma": "nov", "ua": "новий", "lesson": true}, {"form": "riječi", "lemma": "riječ", "ua": "слово", "lesson": false}, {"form": "posao", "lemma": "posao", "ua": "робота / справа", "lesson": true}, {"form": "nije", "lemma": "nije", "ua": "не є; немає (заперечення biti)", "lesson": false}, {"form": "lak", "lemma": "lak", "ua": "легкий", "lesson": false}, {"form": "ali", "lemma": "ali", "ua": "але", "lesson": true}, {"form": "ga", "lemma": "ga", "ua": "його (займенник)", "lesson": false}, {"form": "voli", "lemma": "voljeti", "ua": "любити, подобатися", "lesson": true}]'::jsonb,
        '[{"question_ua": "Ким працює Оксана?", "options": ["Доглядальницею", "Кухаркою", "Прибиральницею"], "answer": "Доглядальницею"}, {"question_ua": "Скільки років пані Марії?", "options": ["Вісімдесят", "Шістдесят", "Дев’яносто"], "answer": "Вісімдесят"}, {"question_ua": "Що Оксана вчить від пані Марії?", "options": ["Нові слова", "Готувати", "Водити машину"], "answer": "Нові слова"}]'::jsonb, 49, 0.898, 24, 'PUBLISHED', 'claude_reading_a1_v1')
on conflict (code) do nothing;
