values ('RD-A1-025', 'A1', 'notice', 'health', 7, 'Години роботи ординації', 'Radno vrijeme ordinacije',
        'ORDINACIJA OBITELJSKE MEDICINE
dr. Ivana Jurić
Ponedjeljak, srijeda, petak: 7 – 14 sati
Utorak, četvrtak: 13 – 20 sati
Na pregled se naručite telefonom ili e-mailom.
Recepte i uputnice možete tražiti e-mailom.
Hitni slučajevi: zovite 194 ili 112.',
        'КАБІНЕТ СІМЕЙНОЇ МЕДИЦИНИ
лікарка Івана Юрич
Понеділок, середа, п’ятниця: 7 – 14 година
Вівторок, четвер: 13 – 20 година
На огляд записуйтеся телефоном або електронною поштою.
Рецепти й направлення можна попросити електронною поштою.
Невідкладні випадки: телефонуйте 194 або 112.',
        '[{"form": "ordinacija", "lemma": "ordinacija", "ua": "кабінет лікаря", "lesson": false}, {"form": "obiteljske", "lemma": "obiteljski", "ua": "сімейний", "lesson": false}, {"form": "medicine", "lemma": "medicina", "ua": "медицина", "lesson": false}, {"form": "dr", "lemma": "dr", "ua": "лікар (скорочення «доктор»)", "lesson": false}, {"form": "ivana", "lemma": "Ivana", "ua": "Івана (ім’я)", "lesson": false}, {"form": "jurić", "lemma": "Jurić", "ua": "Юрич (прізвище)", "lesson": false}, {"form": "ponedjeljak", "lemma": "ponedjeljak", "ua": "понеділок", "lesson": true}, {"form": "srijeda", "lemma": "srijeda", "ua": "середа", "lesson": true}, {"form": "petak", "lemma": "petak", "ua": "п''ятниця", "lesson": true}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "utorak", "lemma": "utorak", "ua": "вівторок", "lesson": true}, {"form": "četvrtak", "lemma": "četvrtak", "ua": "четвер", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "pregled", "lemma": "pregled", "ua": "медичний огляд / обстеження", "lesson": true}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "naručite", "lemma": "naručiti se", "ua": "записатися (на прийом)", "lesson": true}, {"form": "telefonom", "lemma": "telefon", "ua": "телефон", "lesson": true}, {"form": "ili", "lemma": "ili", "ua": "або", "lesson": true}, {"form": "e-mailom", "lemma": "mail", "ua": "електронний лист; імейл", "lesson": true}, {"form": "recepte", "lemma": "recept", "ua": "рецепт", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "uputnice", "lemma": "uputnica", "ua": "направлення", "lesson": true}, {"form": "možete", "lemma": "moći", "ua": "могти", "lesson": true}, {"form": "tražiti", "lemma": "tražiti", "ua": "шукати", "lesson": true}, {"form": "hitni", "lemma": "hitan", "ua": "терміновий", "lesson": true}, {"form": "slučajevi", "lemma": "slučaj", "ua": "випадок", "lesson": false}, {"form": "zovite", "lemma": "zvati", "ua": "дзвонити; кликати", "lesson": true}]'::jsonb,
        '[{"question_ua": "Коли лікарка працює ввечері?", "options": ["У вівторок і четвер", "У понеділок", "У п’ятницю"], "answer": "У вівторок і четвер"}, {"question_ua": "Як записатися на огляд?", "options": ["Телефоном або поштою", "Лише особисто", "Через аптеку"], "answer": "Телефоном або поштою"}, {"question_ua": "Що робити в невідкладному випадку?", "options": ["Дзвонити 194 або 112", "Писати лист", "Чекати до ранку"], "answer": "Дзвонити 194 або 112"}]'::jsonb, 30, 0.867, 25, 'PUBLISHED', 'claude_reading_a1_v1')
on conflict (code) do nothing;
