values ('RD-A1-026', 'A1', 'instruction', 'health', 7, 'Як приймати ліки', 'Uputa o lijeku',
        'SIRUP PROTIV KAŠLJA
Odrasli: jedna žlica tri puta dnevno.
Djeca od 6 do 12 godina: pola žlice tri puta dnevno.
Djeca mlađa od 6 godina: pitajte liječnika.
Lijek uzimajte poslije jela. Ne pijte alkohol.
Ako kašalj traje dulje od tjedan dana, javite se liječniku.',
        'СИРОП ВІД КАШЛЮ
Дорослі: одна ложка тричі на день.
Діти від 6 до 12 років: пів ложки тричі на день.
Діти до 6 років: запитайте лікаря.
Ліки приймайте після їжі. Не пийте алкоголь.
Якщо кашель триває довше за тиждень, зверніться до лікаря.',
        '[{"form": "sirup", "lemma": "sirup", "ua": "сироп", "lesson": false}, {"form": "protiv", "lemma": "protiv", "ua": "проти; від (ліки)", "lesson": false}, {"form": "kašlja", "lemma": "kašalj", "ua": "кашель", "lesson": true}, {"form": "odrasli", "lemma": "odrasli", "ua": "дорослі", "lesson": false}, {"form": "jedna", "lemma": "jedan", "ua": "один", "lesson": true}, {"form": "žlica", "lemma": "žlica", "ua": "ложка", "lesson": true}, {"form": "tri", "lemma": "tri", "ua": "три", "lesson": true}, {"form": "puta", "lemma": "put", "ua": "раз; дорога («dva puta» — двічі)", "lesson": false}, {"form": "dnevno", "lemma": "dnevno", "ua": "щодня; на день", "lesson": true}, {"form": "djeca", "lemma": "djeca", "ua": "діти", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "godina", "lemma": "godina", "ua": "рік", "lesson": true}, {"form": "pola", "lemma": "pola", "ua": "половина", "lesson": true}, {"form": "žlice", "lemma": "žlica", "ua": "ложка", "lesson": true}, {"form": "mlađa", "lemma": "mlad", "ua": "молодий", "lesson": true}, {"form": "pitajte", "lemma": "pitati", "ua": "питати", "lesson": true}, {"form": "liječnika", "lemma": "liječnik", "ua": "лікар", "lesson": true}, {"form": "lijek", "lemma": "lijek", "ua": "ліки / медикамент", "lesson": true}, {"form": "uzimajte", "lemma": "uzimati", "ua": "брати; приймати (ліки)", "lesson": true}, {"form": "poslije", "lemma": "poslije", "ua": "після", "lesson": false}, {"form": "jela", "lemma": "jelo", "ua": "страва", "lesson": true}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true}, {"form": "pijte", "lemma": "piti", "ua": "пити", "lesson": true}, {"form": "alkohol", "lemma": "alkohol", "ua": "алкоголь", "lesson": true}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": false}, {"form": "kašalj", "lemma": "kašalj", "ua": "кашель", "lesson": true}, {"form": "traje", "lemma": "trajati", "ua": "тривати", "lesson": true}, {"form": "dulje", "lemma": "dulje", "ua": "довше", "lesson": false}, {"form": "tjedan", "lemma": "tjedan", "ua": "тиждень", "lesson": true}, {"form": "dana", "lemma": "dan", "ua": "день", "lesson": false}, {"form": "javite", "lemma": "javiti se", "ua": "обізватися; відповісти (на дзвінок); зголоситися", "lesson": true}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "liječniku", "lemma": "liječnik", "ua": "лікар", "lesson": true}]'::jsonb,
        '[{"question_ua": "Скільки сиропу дорослому за раз?", "options": ["Одна ложка", "Пів ложки", "Дві ложки"], "answer": "Одна ложка"}, {"question_ua": "Коли приймати ліки?", "options": ["Після їжі", "Перед сном", "Натщесерце"], "answer": "Після їжі"}, {"question_ua": "Коли звернутися до лікаря?", "options": ["Якщо кашель довше за тиждень", "Одразу", "Через місяць"], "answer": "Якщо кашель довше за тиждень"}]'::jsonb, 41, 0.854, 26, 'PUBLISHED', 'claude_reading_a1_v1')
