values ('RD-A1-027', 'A1', 'message', 'health', 7, 'Нагадування про прийом', 'Podsjetnik za pregled',
        'Poštovana, podsjećamo Vas na pregled kod dr. Jurić sutra u 10:30. Ponesite zdravstvenu iskaznicu i uputnicu. Ako ne možete doći, otkažite termin na broj 01 456 7890. Molimo dođite deset minuta ranije.',
        'Шановна, нагадуємо вам про огляд у лікарки Юрич завтра о 10:30. Візьміть медичну картку страхування й направлення. Якщо не можете прийти, скасуйте прийом за номером 01 456 7890. Просимо прийти на десять хвилин раніше.',
        '[{"form": "poštovana", "lemma": "poštovani", "ua": "шановний", "lesson": false}, {"form": "podsjećamo", "lemma": "podsjećati", "ua": "нагадувати", "lesson": false}, {"form": "vas", "lemma": "vas", "ua": "вас; вам (займенник)", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "pregled", "lemma": "pregled", "ua": "медичний огляд / обстеження", "lesson": true}, {"form": "kod", "lemma": "kod", "ua": "у; біля; в (когось)", "lesson": false}, {"form": "dr", "lemma": "dr", "ua": "лікар (скорочення «доктор»)", "lesson": false}, {"form": "jurić", "lemma": "Jurić", "ua": "Юрич (прізвище)", "lesson": false}, {"form": "sutra", "lemma": "sutra", "ua": "завтра", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "ponesite", "lemma": "ponijeti", "ua": "взяти із собою", "lesson": true}, {"form": "zdravstvenu", "lemma": "zdravstveni", "ua": "медичний; страховий (про картку)", "lesson": false}, {"form": "iskaznicu", "lemma": "iskaznica", "ua": "посвідчення; картка", "lesson": false}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "uputnicu", "lemma": "uputnica", "ua": "направлення", "lesson": true}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": false}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true}, {"form": "možete", "lemma": "moći", "ua": "могти", "lesson": true}, {"form": "doći", "lemma": "doći", "ua": "прийти", "lesson": true}, {"form": "otkažite", "lemma": "otkazati", "ua": "скасувати", "lesson": true}, {"form": "termin", "lemma": "termin", "ua": "(вільний) час; запис (до лікаря, перукаря)", "lesson": true}, {"form": "broj", "lemma": "broj", "ua": "номер / число", "lesson": true}, {"form": "molimo", "lemma": "molim", "ua": "Прошу / Будь ласка / Що (ви сказали)?", "lesson": true}, {"form": "dođite", "lemma": "doći", "ua": "прийти", "lesson": true}, {"form": "deset", "lemma": "deset", "ua": "десять", "lesson": true}, {"form": "minuta", "lemma": "minuta", "ua": "хвилина", "lesson": true}, {"form": "ranije", "lemma": "ranije", "ua": "раніше", "lesson": false}]'::jsonb,
        '[{"question_ua": "Коли огляд?", "options": ["Завтра о 10:30", "Сьогодні о 10:30", "Завтра о 13:00"], "answer": "Завтра о 10:30"}, {"question_ua": "Що треба взяти?", "options": ["Картку страхування й направлення", "Паспорт", "Результати аналізів"], "answer": "Картку страхування й направлення"}, {"question_ua": "На скільки раніше прийти?", "options": ["На десять хвилин", "На годину", "На пів години"], "answer": "На десять хвилин"}]'::jsonb, 28, 0.821, 27, 'PUBLISHED', 'claude_reading_a1_v1')
