values ('RD-A1-028', 'A1', 'chat', 'health', 7, 'Дитина хворіє', 'Dijete je bolesno',
        'Olena: Dobro jutro, Sofija danas ne dolazi u vrtić. Ima temperaturu i kašlje.
Odgojiteljica: Dobro jutro! Žao mi je. Neka se odmara.
Olena: Hvala. Trebam li donijeti potvrdu od liječnika?
Odgojiteljica: Da, kad se vrati u vrtić, trebamo potvrdu od pedijatra.
Olena: U redu. Hvala i lijep dan!',
        'Олена: Доброго ранку, Софія сьогодні не прийде в садок. У неї температура і кашель.
Вихователька: Доброго ранку! Мені шкода. Нехай відпочиває.
Олена: Дякую. Мені потрібно принести довідку від лікаря?
Вихователька: Так, коли вона повернеться в садок, нам потрібна довідка від педіатра.
Олена: Гаразд. Дякую і гарного дня!',
        '[{"form": "olena", "lemma": "Olena", "ua": "Олена (ім’я)", "lesson": false}, {"form": "dobro", "lemma": "dobro", "ua": "добре", "lesson": true}, {"form": "jutro", "lemma": "jutro", "ua": "ранок", "lesson": true}, {"form": "sofija", "lemma": "Sofija", "ua": "Софія (ім’я)", "lesson": false}, {"form": "danas", "lemma": "danas", "ua": "сьогодні", "lesson": true}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true}, {"form": "dolazi", "lemma": "dolaziti", "ua": "приходити", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "vrtić", "lemma": "vrtić", "ua": "дитячий садок", "lesson": true}, {"form": "ima", "lemma": "imati", "ua": "мати", "lesson": true}, {"form": "temperaturu", "lemma": "temperatura", "ua": "температура (жар)", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "kašlje", "lemma": "kašljati", "ua": "кашляти", "lesson": true}, {"form": "odgojiteljica", "lemma": "odgojiteljica", "ua": "вихователька", "lesson": false}, {"form": "žao", "lemma": "žao mi je", "ua": "мені шкода", "lesson": true}, {"form": "mi", "lemma": "mi", "ua": "ми; мені", "lesson": false}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "neka", "lemma": "neka", "ua": "нехай", "lesson": false}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "odmara", "lemma": "odmarati se", "ua": "відпочивати", "lesson": true}, {"form": "hvala", "lemma": "hvala", "ua": "дякую", "lesson": true}, {"form": "trebam", "lemma": "trebati", "ua": "потребувати", "lesson": true}, {"form": "li", "lemma": "li", "ua": "чи (питальна частка)", "lesson": false}, {"form": "donijeti", "lemma": "donijeti", "ua": "принести", "lesson": true}, {"form": "potvrdu", "lemma": "potvrda", "ua": "довідка / підтвердження", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "liječnika", "lemma": "liječnik", "ua": "лікар", "lesson": true}, {"form": "da", "lemma": "da", "ua": "так / що", "lesson": true}, {"form": "kad", "lemma": "kada", "ua": "коли", "lesson": true}, {"form": "vrati", "lemma": "vratiti", "ua": "повернути", "lesson": true}, {"form": "trebamo", "lemma": "trebati", "ua": "потребувати", "lesson": true}, {"form": "pedijatra", "lemma": "pedijatar", "ua": "педіатр", "lesson": true}, {"form": "redu", "lemma": "u redu", "ua": "гаразд; добре", "lesson": true}, {"form": "lijep", "lemma": "lijep", "ua": "красивий", "lesson": true}, {"form": "dan", "lemma": "dan", "ua": "день", "lesson": false}]'::jsonb,
        '[{"question_ua": "Чому Софія не йде в садок?", "options": ["Вона хвора", "Вона на морі", "Садок зачинено"], "answer": "Вона хвора"}, {"question_ua": "Що потрібно, коли Софія повернеться?", "options": ["Довідка від педіатра", "Новий одяг", "Оплата"], "answer": "Довідка від педіатра"}, {"question_ua": "Кому пише Олена?", "options": ["Виховательці", "Лікареві", "Чоловікові"], "answer": "Виховательці"}]'::jsonb, 48, 0.958, 28, 'PUBLISHED', 'claude_reading_a1_v1')
