insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-029', 'A1', 'message', 'small_talk', 8, 'Запрошення на день народження', 'Pozivnica za rođendan',
        'Dragi prijatelji!
U subotu slavim trideseti rođendan i želim vas vidjeti. Zabava je u našem stanu od osam navečer. Imamo hranu i piće, vi donesite dobro raspoloženje! Ako dolazite, javite mi do četvrtka.
Vidimo se,
Ivana',
        'Дорогі друзі!
У суботу я святкую тридцятий день народження і хочу вас побачити. Вечірка в нашій квартирі з восьмої вечора. У нас є їжа й напої, а ви принесіть гарний настрій! Якщо прийдете, дайте мені знати до четверга.
До зустрічі,
Івана',
        '[{"form": "dragi", "lemma": "drag", "ua": "дорогий; милий, приємний", "lesson": true}, {"form": "prijatelji", "lemma": "prijatelj", "ua": "друг", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "subotu", "lemma": "subota", "ua": "субота", "lesson": true}, {"form": "slavim", "lemma": "slaviti", "ua": "святкувати", "lesson": true}, {"form": "trideseti", "lemma": "trideseti", "ua": "тридцятий", "lesson": false}, {"form": "rođendan", "lemma": "rođendan", "ua": "день народження", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "želim", "lemma": "željeti", "ua": "бажати", "lesson": true}, {"form": "vas", "lemma": "vas", "ua": "вас; вам (займенник)", "lesson": false}, {"form": "vidjeti", "lemma": "vidjeti", "ua": "бачити", "lesson": false}, {"form": "zabava", "lemma": "zabava", "ua": "розвага / вечірка", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "našem", "lemma": "naš", "ua": "наш", "lesson": true}, {"form": "stanu", "lemma": "stan", "ua": "квартира", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "osam", "lemma": "osam", "ua": "вісім", "lesson": true}, {"form": "navečer", "lemma": "navečer", "ua": "ввечері", "lesson": true}, {"form": "imamo", "lemma": "imati", "ua": "мати", "lesson": true}, {"form": "hranu", "lemma": "hrana", "ua": "їжа", "lesson": true}, {"form": "piće", "lemma": "piće", "ua": "напій", "lesson": true}, {"form": "vi", "lemma": "vi", "ua": "ви", "lesson": true}, {"form": "donesite", "lemma": "donijeti", "ua": "принести", "lesson": true}, {"form": "dobro", "lemma": "dobro", "ua": "добре", "lesson": true}, {"form": "raspoloženje", "lemma": "raspoloženje", "ua": "настрій", "lesson": false}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": false}, {"form": "dolazite", "lemma": "dolaziti", "ua": "приходити", "lesson": true}, {"form": "javite", "lemma": "javiti se", "ua": "обізватися; відповісти (на дзвінок); зголоситися", "lesson": true}, {"form": "mi", "lemma": "mi", "ua": "ми; мені", "lesson": false}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "četvrtka", "lemma": "četvrtak", "ua": "четвер", "lesson": true}, {"form": "vidimo", "lemma": "vidjeti", "ua": "бачити", "lesson": false}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "ivana", "lemma": "Ivana", "ua": "Івана (ім’я)", "lesson": false}]'::jsonb,
        '[{"question_ua": "Скільки років виповнюється Івані?", "options": ["Тридцять", "Двадцять", "Сорок"], "answer": "Тридцять"}, {"question_ua": "Де вечірка?", "options": ["У квартирі Івани", "У ресторані", "У парку"], "answer": "У квартирі Івани"}, {"question_ua": "До коли треба відповісти?", "options": ["До четверга", "До суботи", "До понеділка"], "answer": "До четверга"}]'::jsonb, 36, 0.944, 29, 'PUBLISHED', 'claude_reading_a1_v1')
