values ('RD-A1-030', 'A1', 'ad', 'small_talk', 8, 'Концерт у парку', 'Koncert u parku',
        'KONCERT U PARKU ZRINJEVAC
Subota, 20 sati
Svira lokalni bend.
Ulaz je besplatan!
Ako pada kiša, koncert je u kazalištu.
Ponesite deku i dobru volju.',
        'КОНЦЕРТ У ПАРКУ ЗРИНЄВАЦ
Субота, 20 година
Грає місцевий гурт.
Вхід вільний!
Якщо йде дощ, концерт відбудеться в театрі.
Візьміть ковдру й гарний настрій.',
        '[{"form": "koncert", "lemma": "koncert", "ua": "концерт", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "parku", "lemma": "park", "ua": "парк", "lesson": true}, {"form": "zrinjevac", "lemma": "Zrinjevac", "ua": "Зриньовац (парк у Загребі)", "lesson": false}, {"form": "subota", "lemma": "subota", "ua": "субота", "lesson": true}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true}, {"form": "svira", "lemma": "svirati", "ua": "грати (на інструменті)", "lesson": false}, {"form": "lokalni", "lemma": "lokalan", "ua": "місцевий", "lesson": false}, {"form": "bend", "lemma": "bend", "ua": "гурт (музичний)", "lesson": true}, {"form": "ulaz", "lemma": "ulaz", "ua": "вхід; під’їзд", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "besplatan", "lemma": "besplatan", "ua": "безкоштовний", "lesson": false}, {"form": "ako", "lemma": "ako", "ua": "якщо", "lesson": false}, {"form": "pada", "lemma": "padati", "ua": "падати («pada kiša» — іде дощ)", "lesson": false}, {"form": "kiša", "lemma": "kiša", "ua": "дощ", "lesson": true}, {"form": "kazalištu", "lemma": "kazalište", "ua": "театр", "lesson": true}, {"form": "ponesite", "lemma": "ponijeti", "ua": "взяти із собою", "lesson": true}, {"form": "deku", "lemma": "deka", "ua": "ковдра; плед", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "dobru", "lemma": "dobar", "ua": "добрий; гарний", "lesson": false}, {"form": "volju", "lemma": "volja", "ua": "воля («dobra volja» — гарний настрій)", "lesson": false}]'::jsonb,
        '[{"question_ua": "Скільки коштує вхід?", "options": ["Безкоштовно", "5 €", "10 €"], "answer": "Безкоштовно"}, {"question_ua": "Що буде, якщо йде дощ?", "options": ["Концерт у театрі", "Концерт скасують", "Концерт у неділю"], "answer": "Концерт у театрі"}, {"question_ua": "Що радять узяти?", "options": ["Ковдру", "Парасольку", "Квиток"], "answer": "Ковдру"}]'::jsonb, 24, 0.792, 30, 'PUBLISHED', 'claude_reading_a1_v1')
