insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-031', 'A1', 'chat', 'small_talk', 8, 'Плануємо похід', 'Planiramo izlet',
        'Marko: Idemo li u nedjelju na Sljeme?
Taras: Može! Kada krećemo?
Marko: Rano, u osam. Nalazimo se na stanici tramvaja.
Taras: Što trebam ponijeti?
Marko: Udobne cipele, vodu i sendvič. Gore je hladnije, uzmi i jaknu.
Taras: Super, vidimo se!',
        'Марко: Підемо в неділю на Слєме?
Тарас: Можна! Коли вирушаємо?
Марко: Рано, о восьмій. Зустрічаємося на трамвайній зупинці.
Тарас: Що мені взяти?
Марко: Зручне взуття, воду й сендвіч. Нагорі холодніше, візьми й куртку.
Тарас: Чудово, до зустрічі!',
        '[{"form": "marko", "lemma": "Marko", "ua": "Марко (ім’я)", "lesson": false}, {"form": "idemo", "lemma": "ići", "ua": "іти, їхати", "lesson": true}, {"form": "li", "lemma": "li", "ua": "чи (питальна частка)", "lesson": false}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "nedjelju", "lemma": "nedjelja", "ua": "неділя", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "sljeme", "lemma": "Sljeme", "ua": "Слєме (гора біля Загреба)", "lesson": false}, {"form": "taras", "lemma": "Taras", "ua": "Тарас (ім’я)", "lesson": false}, {"form": "može", "lemma": "moći", "ua": "могти", "lesson": true}, {"form": "kada", "lemma": "kada", "ua": "коли", "lesson": true}, {"form": "krećemo", "lemma": "kretati", "ua": "вирушати; рушати", "lesson": false}, {"form": "rano", "lemma": "rano", "ua": "рано", "lesson": true}, {"form": "osam", "lemma": "osam", "ua": "вісім", "lesson": true}, {"form": "nalazimo", "lemma": "nalaziti se", "ua": "знаходитися; зустрічатися", "lesson": true}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "stanici", "lemma": "stanica", "ua": "зупинка / станція", "lesson": true}, {"form": "tramvaja", "lemma": "tramvaj", "ua": "трамвай", "lesson": true}, {"form": "što", "lemma": "što", "ua": "що", "lesson": false}, {"form": "trebam", "lemma": "trebati", "ua": "потребувати", "lesson": true}, {"form": "ponijeti", "lemma": "ponijeti", "ua": "взяти із собою", "lesson": true}, {"form": "udobne", "lemma": "udoban", "ua": "зручний", "lesson": true}, {"form": "cipele", "lemma": "cipele", "ua": "взуття / туфлі", "lesson": true}, {"form": "vodu", "lemma": "voda", "ua": "вода", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "sendvič", "lemma": "sendvič", "ua": "сендвіч", "lesson": true}, {"form": "gore", "lemma": "gore", "ua": "вгорі", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "hladnije", "lemma": "hladan", "ua": "холодний", "lesson": true}, {"form": "uzmi", "lemma": "uzeti", "ua": "взяти", "lesson": true}, {"form": "jaknu", "lemma": "jakna", "ua": "куртка", "lesson": true}, {"form": "super", "lemma": "super", "ua": "чудово", "lesson": false}, {"form": "vidimo", "lemma": "vidjeti", "ua": "бачити", "lesson": false}]'::jsonb,
        '[{"question_ua": "Коли вони йдуть у похід?", "options": ["У неділю", "У суботу", "У п’ятницю"], "answer": "У неділю"}, {"question_ua": "Де вони зустрічаються?", "options": ["На трамвайній зупинці", "Біля кафе", "На вокзалі"], "answer": "На трамвайній зупинці"}, {"question_ua": "Чому треба взяти куртку?", "options": ["Нагорі холодніше", "Буде дощ", "Ввечері концерт"], "answer": "Нагорі холодніше"}]'::jsonb, 40, 0.975, 31, 'PUBLISHED', 'claude_reading_a1_v1')
