insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-032', 'A1', 'story', 'small_talk', 8, 'Нові друзі', 'Novi prijatelji',
        'Andrij živi u Rijeci godinu dana. U početku nema prijatelja i često je usamljen. Onda se upisuje na tečaj hrvatskog. Na tečaju upoznaje Marka iz Zagreba i Annu iz Poljske. Sada se nalaze svaki petak u kafiću. Pričaju hrvatski, smiju se i pomažu jedni drugima. Andrij više nije sam.',
        'Андрій живе в Рієці вже рік. Спочатку в нього немає друзів, і він часто самотній. Потім він записується на курс хорватської. На курсі знайомиться з Марком із Загреба та Анною з Польщі. Тепер вони зустрічаються щоп’ятниці в кафе. Розмовляють хорватською, сміються й допомагають одне одному. Андрій більше не сам.',
        '[{"form": "andrij", "lemma": "Andrij", "ua": "Андрій (ім’я)", "lesson": false}, {"form": "živi", "lemma": "živjeti", "ua": "жити", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "rijeci", "lemma": "Rijeka", "ua": "Рієка (місто)", "lesson": true}, {"form": "godinu", "lemma": "godina", "ua": "рік", "lesson": true}, {"form": "dana", "lemma": "dan", "ua": "день", "lesson": false}, {"form": "početku", "lemma": "početak", "ua": "початок", "lesson": false}, {"form": "nema", "lemma": "nema", "ua": "немає", "lesson": false}, {"form": "prijatelja", "lemma": "prijatelj", "ua": "друг", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "često", "lemma": "često", "ua": "часто", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "usamljen", "lemma": "usamljen", "ua": "самотній", "lesson": true}, {"form": "onda", "lemma": "onda", "ua": "потім; тоді", "lesson": false}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "upisuje", "lemma": "upisati", "ua": "записати (в садок, школу); вписати", "lesson": true}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "tečaj", "lemma": "tečaj", "ua": "курс (навчальний / валютний)", "lesson": true}, {"form": "hrvatskog", "lemma": "hrvatski", "ua": "хорватська (мова)", "lesson": true}, {"form": "tečaju", "lemma": "tečaj", "ua": "курс (навчальний / валютний)", "lesson": true}, {"form": "upoznaje", "lemma": "upoznati", "ua": "познайомитися / пізнати", "lesson": true}, {"form": "marka", "lemma": "Marko", "ua": "Марко (ім’я)", "lesson": false}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": false}, {"form": "zagreba", "lemma": "Zagreb", "ua": "Загреб", "lesson": false}, {"form": "annu", "lemma": "Anna", "ua": "Анна (ім’я)", "lesson": false}, {"form": "poljske", "lemma": "Poljska", "ua": "Польща", "lesson": false}, {"form": "sada", "lemma": "sada", "ua": "зараз", "lesson": false}, {"form": "nalaze", "lemma": "nalaziti se", "ua": "знаходитися; зустрічатися", "lesson": true}, {"form": "svaki", "lemma": "svaki", "ua": "кожен", "lesson": false}, {"form": "petak", "lemma": "petak", "ua": "п''ятниця", "lesson": true}, {"form": "kafiću", "lemma": "kafić", "ua": "кафе / кав''ярня", "lesson": true}, {"form": "pričaju", "lemma": "pričati", "ua": "розповідати; розмовляти", "lesson": true}, {"form": "hrvatski", "lemma": "hrvatski", "ua": "хорватська (мова)", "lesson": true}, {"form": "smiju", "lemma": "smijati se", "ua": "сміятися", "lesson": true}, {"form": "pomažu", "lemma": "pomagati", "ua": "допомагати", "lesson": true}, {"form": "jedni", "lemma": "jedan", "ua": "один", "lesson": true}, {"form": "drugima", "lemma": "drugi", "ua": "другий; інший", "lesson": false}, {"form": "više", "lemma": "više", "ua": "більше", "lesson": true}, {"form": "nije", "lemma": "nije", "ua": "не є; немає (заперечення biti)", "lesson": false}, {"form": "sam", "lemma": "sam", "ua": "сам (один)", "lesson": false}]'::jsonb,
        '[{"question_ua": "Де живе Андрій?", "options": ["У Рієці", "У Загребі", "У Спліті"], "answer": "У Рієці"}, {"question_ua": "Де він знайомиться з друзями?", "options": ["На курсі хорватської", "На роботі", "У спортзалі"], "answer": "На курсі хорватської"}, {"question_ua": "Коли вони зустрічаються?", "options": ["Щоп’ятниці", "Щонеділі", "Щодня"], "answer": "Щоп’ятниці"}]'::jsonb, 49, 0.939, 32, 'PUBLISHED', 'claude_reading_a1_v1')
