insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-033', 'A1', 'news', 'travel', 9, 'Прогноз погоди', 'Vremenska prognoza',
        'Sutra je na moru sunčano i toplo, do 28 stupnjeva. U Zagrebu i na sjeveru je oblačno, a poslijepodne pada kiša. Temperatura je od 15 do 20 stupnjeva. U planinama puše jak vjetar. Na Jadranu puše jugo, zato trajekti mogu kasniti.',
        'Завтра на морі сонячно й тепло, до 28 градусів. У Загребі й на півночі хмарно, а після обіду йде дощ. Температура від 15 до 20 градусів. У горах дме сильний вітер. На Адріатиці дме юго, тому пороми можуть запізнюватися.',
        '[{"form": "sutra", "lemma": "sutra", "ua": "завтра", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "moru", "lemma": "more", "ua": "море", "lesson": true}, {"form": "sunčano", "lemma": "sunčano", "ua": "сонячно", "lesson": false}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "toplo", "lemma": "topao", "ua": "теплий", "lesson": true}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "stupnjeva", "lemma": "stupanj", "ua": "ступінь, градус", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "zagrebu", "lemma": "Zagreb", "ua": "Загреб", "lesson": false}, {"form": "sjeveru", "lemma": "sjever", "ua": "північ", "lesson": true}, {"form": "oblačno", "lemma": "oblačno", "ua": "хмарно", "lesson": false}, {"form": "a", "lemma": "a", "ua": "а; і", "lesson": false}, {"form": "poslijepodne", "lemma": "poslijepodne", "ua": "після обіду; пополудні", "lesson": true}, {"form": "pada", "lemma": "padati", "ua": "падати («pada kiša» — іде дощ)", "lesson": false}, {"form": "kiša", "lemma": "kiša", "ua": "дощ", "lesson": true}, {"form": "temperatura", "lemma": "temperatura", "ua": "температура (жар)", "lesson": true}, {"form": "od", "lemma": "od", "ua": "від; з", "lesson": false}, {"form": "planinama", "lemma": "planina", "ua": "гора / гірський масив", "lesson": true}, {"form": "puše", "lemma": "puhati", "ua": "дути (про вітер)", "lesson": false}, {"form": "jak", "lemma": "jak", "ua": "сильний", "lesson": false}, {"form": "vjetar", "lemma": "vjetar", "ua": "вітер", "lesson": true}, {"form": "jadranu", "lemma": "Jadran", "ua": "Адріатика (Адріатичне море)", "lesson": false}, {"form": "jugo", "lemma": "jugo", "ua": "юго (теплий південний вітер)", "lesson": false}, {"form": "zato", "lemma": "zato", "ua": "тому", "lesson": false}, {"form": "trajekti", "lemma": "trajekt", "ua": "пором", "lesson": true}, {"form": "mogu", "lemma": "moći", "ua": "могти", "lesson": true}, {"form": "kasniti", "lemma": "kasniti", "ua": "запізнюватися", "lesson": true}]'::jsonb,
        '[{"question_ua": "Яка погода завтра на морі?", "options": ["Сонячно й тепло", "Дощ", "Сніг"], "answer": "Сонячно й тепло"}, {"question_ua": "Що буде в Загребі після обіду?", "options": ["Дощ", "Сонце", "Туман"], "answer": "Дощ"}, {"question_ua": "Чому пороми можуть запізнюватися?", "options": ["Через вітер юго", "Через свято", "Через туман"], "answer": "Через вітер юго"}]'::jsonb, 38, 0.816, 33, 'PUBLISHED', 'claude_reading_a1_v1')
