values ('RD-A1-034', 'A1', 'notice', 'travel', 9, 'Правила в національному парку', 'Pravila u nacionalnom parku',
        'DOBRO DOŠLI U NACIONALNI PARK!
Hodajte samo po stazama.
Kupanje u jezerima je zabranjeno.
Ne hranite životinje i ne berite cvijeće.
Smeće nosite sa sobom.
Psi moraju biti na povodcu.
Hvala što čuvate prirodu!',
        'ЛАСКАВО ПРОСИМО ДО НАЦІОНАЛЬНОГО ПАРКУ!
Ходіть лише стежками.
Купатися в озерах заборонено.
Не годуйте тварин і не зривайте квітів.
Сміття забирайте з собою.
Собаки мають бути на повідку.
Дякуємо, що бережете природу!',
        '[{"form": "dobro", "lemma": "dobro", "ua": "добре", "lesson": true}, {"form": "došli", "lemma": "doći", "ua": "прийти", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "nacionalni", "lemma": "nacionalni park", "ua": "національний парк", "lesson": true}, {"form": "park", "lemma": "park", "ua": "парк", "lesson": true}, {"form": "hodajte", "lemma": "hodati", "ua": "ходити", "lesson": false}, {"form": "samo", "lemma": "samo", "ua": "тільки; лише", "lesson": false}, {"form": "po", "lemma": "po", "ua": "по; за (чимось)", "lesson": false}, {"form": "stazama", "lemma": "staza", "ua": "стежка; доріжка", "lesson": true}, {"form": "kupanje", "lemma": "kupanje", "ua": "купання", "lesson": false}, {"form": "jezerima", "lemma": "jezero", "ua": "озеро", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "zabranjeno", "lemma": "zabranjeno", "ua": "заборонено", "lesson": true}, {"form": "ne", "lemma": "ne", "ua": "ні", "lesson": true}, {"form": "hranite", "lemma": "hraniti", "ua": "годувати", "lesson": true}, {"form": "životinje", "lemma": "životinja", "ua": "тварина", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "berite", "lemma": "brati", "ua": "зривати; збирати", "lesson": false}, {"form": "cvijeće", "lemma": "cvijeće", "ua": "квіти", "lesson": false}, {"form": "smeće", "lemma": "smeće", "ua": "сміття", "lesson": true}, {"form": "nosite", "lemma": "nositi", "ua": "носити / одягати", "lesson": true}, {"form": "sa", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "sobom", "lemma": "sebe", "ua": "себе", "lesson": false}, {"form": "psi", "lemma": "pas", "ua": "собака", "lesson": true}, {"form": "moraju", "lemma": "morati", "ua": "мусити / бути зобов''язаним", "lesson": true}, {"form": "biti", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "povodcu", "lemma": "povodac", "ua": "повідець", "lesson": true}, {"form": "hvala", "lemma": "hvala", "ua": "дякую", "lesson": true}, {"form": "što", "lemma": "što", "ua": "що", "lesson": false}, {"form": "čuvate", "lemma": "čuvati", "ua": "берегти", "lesson": false}, {"form": "prirodu", "lemma": "priroda", "ua": "природа", "lesson": true}]'::jsonb,
        '[{"question_ua": "Чи можна купатися в озерах?", "options": ["Ні, заборонено", "Так", "Лише влітку"], "answer": "Ні, заборонено"}, {"question_ua": "Де можна ходити?", "options": ["Лише стежками", "Де завгодно", "Лише біля озер"], "answer": "Лише стежками"}, {"question_ua": "Що зробити зі сміттям?", "options": ["Забрати з собою", "Залишити біля стежки", "Спалити"], "answer": "Забрати з собою"}]'::jsonb, 34, 0.853, 34, 'PUBLISHED', 'claude_reading_a1_v1')
