insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-035', 'A1', 'article', 'travel', 9, 'Адвент у Загребі', 'Advent u Zagrebu',
        'Advent u Zagrebu počinje krajem studenoga i traje do početka siječnja. Grad je pun svjetla, a na trgovima su male kućice s hranom i pićem. Ljudi piju kuhano vino i jedu fritule i kobasice. Na klizalištu se kližu djeca i odrasli. Svake godine dolazi puno turista iz cijelog svijeta.',
        'Адвент у Загребі починається наприкінці листопада й триває до початку січня. Місто сповнене вогнів, а на площах — маленькі будиночки з їжею та напоями. Люди п’ють глінтвейн і їдять фрітуле та ковбаски. На ковзанці катаються діти й дорослі. Щороку приїжджає багато туристів з усього світу.',
        '[{"form": "advent", "lemma": "advent", "ua": "адвент (час перед Різдвом)", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "zagrebu", "lemma": "Zagreb", "ua": "Загреб", "lesson": false}, {"form": "počinje", "lemma": "počinjati", "ua": "починати", "lesson": true}, {"form": "krajem", "lemma": "kraj", "ua": "кінець; край, місцевість", "lesson": true}, {"form": "studenoga", "lemma": "studeni", "ua": "листопад", "lesson": true}, {"form": "i", "lemma": "i", "ua": "і; та", "lesson": false}, {"form": "traje", "lemma": "trajati", "ua": "тривати", "lesson": true}, {"form": "do", "lemma": "do", "ua": "до", "lesson": false}, {"form": "početka", "lemma": "početak", "ua": "початок", "lesson": false}, {"form": "siječnja", "lemma": "siječanj", "ua": "січень", "lesson": true}, {"form": "grad", "lemma": "grad", "ua": "місто", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "pun", "lemma": "pun", "ua": "повний", "lesson": true}, {"form": "svjetla", "lemma": "svjetlo", "ua": "світло / фара", "lesson": true}, {"form": "a", "lemma": "a", "ua": "а; і", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "trgovima", "lemma": "trg", "ua": "площа", "lesson": true}, {"form": "su", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "male", "lemma": "mali", "ua": "малий", "lesson": true}, {"form": "kućice", "lemma": "kućica", "ua": "будиночок; кіоск", "lesson": false}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "hranom", "lemma": "hrana", "ua": "їжа", "lesson": true}, {"form": "pićem", "lemma": "piće", "ua": "напій", "lesson": true}, {"form": "ljudi", "lemma": "ljudi", "ua": "люди", "lesson": false}, {"form": "piju", "lemma": "piti", "ua": "пити", "lesson": true}, {"form": "kuhano", "lemma": "kuhan", "ua": "варений", "lesson": true}, {"form": "vino", "lemma": "vino", "ua": "вино", "lesson": true}, {"form": "jedu", "lemma": "jesti", "ua": "їсти", "lesson": true}, {"form": "fritule", "lemma": "fritule", "ua": "фрітуле (маленькі пончики)", "lesson": true}, {"form": "kobasice", "lemma": "kobasica", "ua": "сосиска; ковбаска", "lesson": true}, {"form": "klizalištu", "lemma": "klizalište", "ua": "ковзанка", "lesson": false}, {"form": "se", "lemma": "se", "ua": "себе; -ся (частка дієслова)", "lesson": false}, {"form": "kližu", "lemma": "klizati se", "ua": "кататися на ковзанах", "lesson": false}, {"form": "djeca", "lemma": "djeca", "ua": "діти", "lesson": true}, {"form": "odrasli", "lemma": "odrasli", "ua": "дорослі", "lesson": false}, {"form": "svake", "lemma": "svaki", "ua": "кожен", "lesson": false}, {"form": "godine", "lemma": "godina", "ua": "рік", "lesson": true}, {"form": "dolazi", "lemma": "dolaziti", "ua": "приходити", "lesson": true}, {"form": "puno", "lemma": "puno", "ua": "багато", "lesson": true}, {"form": "turista", "lemma": "turist", "ua": "турист", "lesson": false}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": false}, {"form": "cijelog", "lemma": "cijel", "ua": "цілий; весь", "lesson": false}, {"form": "svijeta", "lemma": "svijet", "ua": "світ", "lesson": false}]'::jsonb,
        '[{"question_ua": "Коли починається адвент?", "options": ["Наприкінці листопада", "У січні", "Улітку"], "answer": "Наприкінці листопада"}, {"question_ua": "Що п’ють люди?", "options": ["Глінтвейн", "Пиво", "Сік"], "answer": "Глінтвейн"}, {"question_ua": "Хто катається на ковзанці?", "options": ["Діти й дорослі", "Лише діти", "Лише туристи"], "answer": "Діти й дорослі"}]'::jsonb, 49, 0.837, 35, 'PUBLISHED', 'claude_reading_a1_v1')
