alse}, {"form": "stranom", "lemma": "stran", "ua": "іноземний", "lesson": false}, {"form": "jeziku", "lemma": "jezik", "ua": "мова", "lesson": true}, {"form": "prevodi", "lemma": "prevoditi", "ua": "перекладати", "lesson": false}, {"form": "sudski", "lemma": "sudski tumač", "ua": "присяжний перекладач", "lesson": true}, {"form": "tumač", "lemma": "sudski tumač", "ua": "присяжний перекладач", "lesson": true}, {"form": "šalter", "lemma": "šalter", "ua": "віконце (в установі)", "lesson": true}, {"form": "dolazite", "lemma": "dolaziti", "ua": "приходити", "lesson": true}, {"form": "s", "lemma": "s", "ua": "з (разом із)", "lesson": false}, {"form": "brojem", "lemma": "broj", "ua": "номер / число", "lesson": true}, {"form": "iz", "lemma": "iz", "ua": "з (звідки)", "lesson": false}, {"form": "automata", "lemma": "automat", "ua": "автомат (паркомат, автомат з продажу)", "lesson": true}, {"form": "radno", "lemma": "radno vrijeme", "ua": "робочий час", "lesson": true}, {"form": "vrijeme", "lemma": "vrijeme", "ua": "погода / час", "lesson": true}, {"form": "sati", "lemma": "sat", "ua": "годинник / година", "lesson": true}]'::jsonb,
