insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-039', 'A1', 'ad', 'administration', 10, 'Безкоштовний курс хорватської', 'Besplatni tečaj hrvatskog',
        'BESPLATNI TEČAJ HRVATSKOG ZA STRANCE
Grad Zagreb organizira tečaj za početnike.
Nastava je dva puta tjedno, navečer, u gradskoj knjižnici.
Tečaj traje tri mjeseca. Na kraju dobivate svjedodžbu.
Broj mjesta je ograničen.
Prijave: osobno u knjižnici ili na stranici grada.',
        'БЕЗКОШТОВНИЙ КУРС ХОРВАТСЬКОЇ ДЛЯ ІНОЗЕМЦІВ
Місто Загреб організовує курс для початківців.
Заняття двічі на тиждень, увечері, у міській бібліотеці.
Курс триває три місяці. Наприкінці отримуєте свідоцтво.
Кількість місць обмежена.
Реєстрація: особисто в бібліотеці або на сайті міста.',
        '[{"form": "besplatni", "lemma": "besplatan", "ua": "безкоштовний", "lesson": false}, {"form": "tečaj", "lemma": "tečaj", "ua": "курс (навчальний / валютний)", "lesson": true}, {"form": "hrvatskog", "lemma": "hrvatski", "ua": "хорватська (мова)", "lesson": true}, {"form": "za", "lemma": "za", "ua": "для; за", "lesson": false}, {"form": "strance", "lemma": "stranac", "ua": "іноземець", "lesson": true}, {"form": "grad", "lemma": "grad", "ua": "місто", "lesson": true}, {"form": "zagreb", "lemma": "Zagreb", "ua": "Загреб", "lesson": false}, {"form": "organizira", "lemma": "organizirati", "ua": "організовувати", "lesson": false}, {"form": "početnike", "lemma": "početnik", "ua": "початківець", "lesson": false}, {"form": "nastava", "lemma": "nastava", "ua": "заняття; навчання (уроки)", "lesson": true}, {"form": "je", "lemma": "biti", "ua": "бути; є", "lesson": false}, {"form": "dva", "lemma": "dva", "ua": "два", "lesson": true}, {"form": "puta", "lemma": "put", "ua": "раз; дорога («dva puta» — двічі)", "lesson": false}, {"form": "tjedno", "lemma": "tjedno", "ua": "щотижня; на тиждень", "lesson": true}, {"form": "navečer", "lemma": "navečer", "ua": "ввечері", "lesson": true}, {"form": "u", "lemma": "u", "ua": "у; в", "lesson": false}, {"form": "gradskoj", "lemma": "gradski", "ua": "міський", "lesson": false}, {"form": "knjižnici", "lemma": "knjižnica", "ua": "бібліотека", "lesson": true}, {"form": "traje", "lemma": "trajati", "ua": "тривати", "lesson": true}, {"form": "tri", "lemma": "tri", "ua": "три", "lesson": true}, {"form": "mjeseca", "lemma": "mjesec", "ua": "місяць", "lesson": false}, {"form": "na", "lemma": "na", "ua": "на", "lesson": false}, {"form": "kraju", "lemma": "kraj", "ua": "кінець; край, місцевість", "lesson": true}, {"form": "dobivate", "lemma": "dobiti", "ua": "отримати / здобути", "lesson": true}, {"form": "svjedodžbu", "lemma": "svjedodžba", "ua": "свідоцтво; атестат", "lesson": true}, {"form": "broj", "lemma": "broj", "ua": "номер / число", "lesson": true}, {"form": "mjesta", "lemma": "mjesto", "ua": "місце", "lesson": true}, {"form": "ograničen", "lemma": "ograničen", "ua": "обмежений", "lesson": false}, {"form": "prijave", "lemma": "prijava", "ua": "заявка; реєстрація", "lesson": false}, {"form": "osobno", "lemma": "osobno", "ua": "особисто", "lesson": false}, {"form": "ili", "lemma": "ili", "ua": "або", "lesson": true}, {"form": "stranici", "lemma": "stranica", "ua": "сторінка", "lesson": true}, {"form": "grada", "lemma": "grad", "ua": "місто", "lesson": true}]'::jsonb,
        '[{"question_ua": "Де відбуваються заняття?", "options": ["У міській бібліотеці", "У школі", "Онлайн"], "answer": "У міській бібліотеці"}, {"question_ua": "Скільки триває курс?", "options": ["Три місяці", "Рік", "Місяць"], "answer": "Три місяці"}, {"question_ua": "Що отримують наприкінці?", "options": ["Свідоцтво", "Гроші", "Книжку"], "answer": "Свідоцтво"}]'::jsonb, 40, 0.800, 39, 'PUBLISHED', 'claude_reading_a1_v1')
