insert into public.reading_texts (code, cefr, text_type, situation, module_order, title_ua, title_hr, body_hr, body_ua, glossary, questions, word_count, known_ratio, order_index, status, source)
values ('RD-A1-040', 'A1', 'story', 'small_talk', 10, 'Мій рік у Хорватії', 'Moja godina u Hrvatskoj',
        'Zovem se Olena i živim u Zagrebu već godinu dana. Radim u hotelu, a moja djeca idu u školu i u vrtić. Hrvatski je sličan ukrajinskom, ali često se zbunim. Ljudi su ljubazni i strpljivi kad govorim polako. Nedostaje mi domovina i moja obitelj, ali ovdje imamo mir. Svaki dan učim nove riječi i sve više razumijem.',
        'Мене звати Олена, і я живу в Загребі вже рік. Я працюю в готелі, а мої діти ходять до школи й у садок. Хорватська схожа на українську, але я часто плутаюся. Люди привітні й терплячі, коли я говорю повільно. Мені бракує батьківщини й моєї родини, але тут у нас мир. Щодня я вчу нові слова й розумію дедалі більше.',
