-- Журнал перевірки (один запис на текст)
insert into public.content_reviews (entity_type, entity_id, from_status, to_status, verdict, reviewer_kind, findings, notes)
select 'reading_text', r.id, null, 'PUBLISHED', 'auto_passed', 'ai', '[]'::jsonb, 'Бета: тексти для читання A1 (§6) за запитом власника 2026-10-14 (reading_a1_v1). Потрібна перевірка носієм.'
from public.reading_texts r
where r.source = 'claude_reading_a1_v1'
  and not exists (select 1 from public.content_reviews c where c.entity_id = r.id and c.notes = 'Бета: тексти для читання A1 (§6) за запитом власника 2026-10-14 (reading_a1_v1). Потрібна перевірка носієм.');

-- Самоперевірка: якщо щось не так — усе відкочується
do $$
declare v_total int; v_bad int;
begin
  select count(*) into v_total from public.reading_texts where source = 'claude_reading_a1_v1' and status = 'PUBLISHED';
  select count(*) into v_bad from public.reading_texts where source = 'claude_reading_a1_v1'
     and (jsonb_array_length(questions) <> 3 or jsonb_array_length(glossary) < 10 or known_ratio < 0.75);
  if v_total < 40 then raise exception 'Текстів %, очікувалось 40', v_total; end if;
  if v_bad > 0 then raise exception '% текстів без питань чи словничка', v_bad; end if;
  raise notice 'Готово: текстів для читання A1 — %', v_total;
end $$;

commit;
